import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type ProjectStatus = 'Proposed' | 'Ongoing' | 'Completed';

export interface User {
  id: string;
  name: string;
  role: string;
  college: string;
  bio: string;
  avatar: string;
  skills: string[];
  githubUrl: string;
  linkedinUrl: string;
  reputation: number;
}

export interface Task {
  id: string;
  title: string;
  status: 'todo' | 'in-progress' | 'done';
  assignee?: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  communityId: string;
  status: ProjectStatus;
  techStack: string[];
  contributors: string[];
  tasks: Task[];
  githubRepo?: string;
}

export interface Community {
  id: string;
  name: string;
  description: string;
  icon: string;
  memberCount: number;
  projectCount: number;
  channels: Channel[];
}

export interface Channel {
  id: string;
  name: string;
  type: 'chat' | 'project-list';
}

export interface ChatMessage {
  id: string;
  senderId: string;
  content: string;
  timestamp: string;
}

import React from 'react';
import { MOCK_COMMUNITIES } from '../constants';
import { Community } from '../types';

interface SidebarProps {
  activeCommunityId: string | null;
  onSelectCommunity: (id: string | null) => void;
  onOpenFeed: () => void;
  onOpenProfile: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeCommunityId, onSelectCommunity, onOpenFeed, onOpenProfile }) => {
  return (
    <div className="w-[72px] bg-[#020617] flex flex-col items-center py-3 space-y-4 flex-shrink-0">
      {/* App Logo / Feed Home */}
      <button 
        onClick={onOpenFeed}
        className={`w-12 h-12 rounded-[24px] bg-indigo-600 flex items-center justify-center transition-all duration-300 hover:rounded-[16px] hover:bg-indigo-500 group relative`}
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
        </svg>
        <span className="absolute left-16 bg-slate-800 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap z-50 pointer-events-none">Home Feed</span>
      </button>

      <div className="w-8 h-[2px] bg-slate-800 rounded-full" />

      {/* Community List */}
      {MOCK_COMMUNITIES.map((community) => (
        <button
          key={community.id}
          onClick={() => onSelectCommunity(community.id)}
          className={`group relative w-12 h-12 flex items-center justify-center transition-all duration-300 overflow-hidden ${
            activeCommunityId === community.id 
              ? 'rounded-[16px] bg-indigo-600 text-white' 
              : 'rounded-[24px] bg-slate-800 text-slate-400 hover:rounded-[16px] hover:bg-indigo-600 hover:text-white'
          }`}
        >
          <span className="text-xl font-bold">{community.icon}</span>
          <span className="absolute left-16 bg-slate-800 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap z-50 pointer-events-none">{community.name}</span>
        </button>
      ))}

      <button className="w-12 h-12 rounded-[24px] bg-slate-800 flex items-center justify-center text-teal-400 transition-all duration-300 hover:rounded-[16px] hover:bg-teal-600 hover:text-white group relative">
        <span className="text-2xl font-light">+</span>
        <span className="absolute left-16 bg-slate-800 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap z-50 pointer-events-none">Join Community</span>
      </button>

      <div className="mt-auto pt-4 flex flex-col items-center space-y-4">
        <button 
          onClick={onOpenProfile}
          className="w-12 h-12 rounded-full border-2 border-transparent hover:border-indigo-500 overflow-hidden transition-all group relative"
        >
          <img src="https://picsum.photos/seed/alex/100" alt="Profile" className="w-full h-full object-cover" />
          <span className="absolute left-16 bg-slate-800 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap z-50 pointer-events-none">Your Profile</span>
        </button>
      </div>
    </div>
  );
};

export default Sidebar;

import React from 'react';
import { Community, Channel } from '../types';

