export default ChannelPanel;

import React from 'react';
import { Project, Task, MOCK_USERS } from '../types';

interface ProjectViewProps {
  project: Project;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project }) => {
  const getTasksByStatus = (status: Task['status']) => project.tasks.filter(t => t.status === status);

  const getAssigneeAvatar = (userId?: string) => {
    const user = MOCK_USERS.find(u => u.id === userId);
    return user ? user.avatar : 'https://picsum.photos/seed/placeholder/50';
  };

  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-[#1e293b]">
      {/* Project Header */}
      <div className="h-14 border-b border-slate-800 px-6 flex items-center justify-between bg-[#0f172a] shadow-sm">
        <div className="flex items-center space-x-4">
          <div className="p-2 bg-indigo-500/10 rounded-lg">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
          </div>
          <div>
            <h2 className="text-lg font-bold text-white">{project.name}</h2>
            <p className="text-xs text-slate-400">Status: <span className="text-teal-400 font-semibold">{project.status}</span></p>
          </div>
        </div>
        <div className="flex items-center -space-x-2">
          {project.contributors.map(cId => {
            const u = MOCK_USERS.find(user => user.id === cId);
            return (
              <img 
                key={cId}
                src={u?.avatar} 
                className="w-8 h-8 rounded-full border-2 border-slate-900" 
                title={u?.name}
              />
            );
          })}
          <button className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-slate-400 border-2 border-slate-900 hover:text-white transition-colors">
            +
          </button>
        </div>
      </div>

      {/* Board Layout */}
      <div className="flex-1 overflow-x-auto p-6 flex space-x-6 custom-scrollbar">
        {['todo', 'in-progress', 'done'].map((status) => (
          <div key={status} className="w-80 flex-shrink-0 flex flex-col">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-2">
                <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest">{status.replace('-', ' ')}</h3>
                <span className="bg-slate-800 text-slate-400 text-[10px] px-2 py-0.5 rounded-full">{getTasksByStatus(status as any).length}</span>
              </div>
              <button className="text-slate-500 hover:text-indigo-400">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                  <path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z" />
                </svg>
              </button>
            </div>

            <div className="flex-1 bg-slate-900/30 rounded-xl p-3 space-y-3 overflow-y-auto custom-scrollbar border border-slate-800/50">
              {getTasksByStatus(status as any).map(task => (
                <div key={task.id} className="bg-[#1e293b] p-4 rounded-lg shadow-sm border border-slate-800 hover:border-slate-700 transition-all group cursor-pointer">
                  <p className="text-sm text-slate-200 mb-3 font-medium">{task.title}</p>
                  <div className="flex items-center justify-between">
                    <div className="flex space-x-1">
                      {project.techStack.slice(0, 2).map(tech => (
                        <span key={tech} className="text-[10px] bg-indigo-500/10 text-indigo-400 px-1.5 py-0.5 rounded uppercase font-bold tracking-tighter">{tech}</span>
                      ))}
                    </div>
                    {task.assignee && (
                      <img src={getAssigneeAvatar(task.assignee)} className="w-6 h-6 rounded-full border border-slate-800" alt="Assignee" />
                    )}
                  </div>
                </div>
              ))}
              <button className="w-full py-2 flex items-center justify-center space-x-2 text-slate-500 hover:text-slate-300 hover:bg-slate-800/50 rounded-lg transition-all border border-dashed border-slate-800 mt-2">
                <span className="text-lg">+</span>
                <span className="text-xs font-bold uppercase tracking-wider">Add Task</span>
              </button>
            </div>
          </div>
        ))}

        {/* Project Info Panel */}
        <div className="w-80 flex-shrink-0 flex flex-col space-y-6">
          <div className="bg-[#0f172a] p-6 rounded-2xl border border-slate-800">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">About Project</h3>
            <p className="text-sm text-slate-300 leading-relaxed">
              {project.description}
            </p>
            <div className="mt-6 flex flex-wrap gap-2">
              {project.techStack.map(tech => (
                <span key={tech} className="text-xs bg-slate-800 text-slate-300 px-2 py-1 rounded-md border border-slate-700">
                  {tech}
                </span>
              ))}
            </div>
            <button className="w-full mt-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-indigo-900/20">
              Open Github Repo
            </button>
          </div>

          <div className="bg-[#0f172a] p-6 rounded-2xl border border-slate-800">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Activity Log</h3>
            <div className="space-y-4">
              {[1, 2, 3].map(i => (
                <div key={i} className="flex space-x-3">
                  <div className="w-2 h-2 rounded-full bg-teal-500 mt-1.5" />
                  <div>
                    <p className="text-[12px] text-slate-300"><span className="font-bold">Alex</span> completed "UI Setup"</p>
                    <p className="text-[10px] text-slate-500">2 hours ago</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProjectView;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Feed from './components/Feed';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project } from './types';

const App: React.FC = () => {
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(MOCK_COMMUNITIES[0].id);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(MOCK_COMMUNITIES[0].channels[3].id);
  const [view, setView] = useState<'community' | 'profile' | 'feed'>('community');
  const [isLanding, setIsLanding] = useState(true);

  const activeCommunity = MOCK_COMMUNITIES.find(c => c.id === activeCommunityId) || null;
  const currentProject = MOCK_PROJECTS[0]; // Simplified for demo

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = MOCK_COMMUNITIES.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
    }
    setView('community');
  };

  const handleOpenFeed = () => {
    setView('feed');
    setActiveCommunityId(null);
  };

  const handleOpenProfile = () => {
    setView('profile');
    setActiveCommunityId(null);
  };

  if (isLanding) {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-center">
        <div className="max-w-4xl space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="flex items-center justify-center space-x-4 mb-12">
            <div className="w-16 h-16 bg-indigo-600 rounded-[24px] flex items-center justify-center shadow-2xl shadow-indigo-900/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 10-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" />
              </svg>
            </div>
            <h1 className="text-6xl font-black text-white tracking-tighter italic">NEXORA</h1>
          </div>

          <div className="space-y-4">
            <h2 className="text-4xl md:text-5xl font-bold text-slate-100">Connect. Collab. Craft.</h2>
            <p className="text-xl text-slate-400 max-w-2xl mx-auto leading-relaxed">
              Where students transition from passive connections to active contributors. 
              Build real projects, join elite communities, and evolve your career.
            </p>
          </div>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 pt-12">
            <button 
              onClick={() => setIsLanding(false)}
              className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-bold text-lg hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-900/30 w-full sm:w-auto"
            >
              Get Started
            </button>
            <button className="px-10 py-4 bg-slate-800 text-slate-200 rounded-2xl font-bold text-lg hover:bg-slate-700 transition-all w-full sm:w-auto border border-slate-700">
              Explore Communities
            </button>
          </div>

          <div className="pt-24 grid grid-cols-1 md:grid-cols-3 gap-8 text-left">
            <div className="p-6 bg-slate-900/40 rounded-3xl border border-slate-800">
              <div className="text-indigo-400 font-bold mb-2">01</div>
              <h3 className="text-white font-bold mb-2">Project First</h3>
              <p className="text-slate-400 text-sm">Every interaction on Nexora centers around creating something tangible.</p>
            </div>
            <div className="p-6 bg-slate-900/40 rounded-3xl border border-slate-800">
              <div className="text-teal-400 font-bold mb-2">02</div>
              <h3 className="text-white font-bold mb-2">Proof of Work</h3>
              <p className="text-slate-400 text-sm">Profiles evolve based on actual contributions, not just titles.</p>
            </div>
            <div className="p-6 bg-slate-900/40 rounded-3xl border border-slate-800">
              <div className="text-cyan-400 font-bold mb-2">03</div>
              <h3 className="text-white font-bold mb-2">Unified Stack</h3>
              <p className="text-slate-400 text-sm">Discussions, collaboration, and networking in one specialized home.</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-[#020617] overflow-hidden">
      <Sidebar 
        activeCommunityId={activeCommunityId} 
        onSelectCommunity={handleSelectCommunity} 
        onOpenFeed={handleOpenFeed}
        onOpenProfile={handleOpenProfile}
      />

      {view === 'community' && activeCommunity && (
        <>
          <ChannelPanel 
            community={activeCommunity} 
            activeChannelId={activeChannelId}
            onSelectChannel={setActiveChannelId}
            onStartProject={() => {}} 
          />
          <ProjectView project={currentProject} />
        </>
      )}

      {view === 'profile' && (
        <Profile user={MOCK_USERS[0]} />
      )}

      {view === 'feed' && (
        <Feed />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { Project, Task } from '../types';
// Fix: MOCK_USERS is exported from constants.tsx, not types.ts
import { MOCK_USERS } from '../constants';

interface ProjectViewProps {
  project: Project;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project }) => {
  const getTasksByStatus = (status: Task['status']) => project.tasks.filter(t => t.status === status);

  const getAssigneeAvatar = (userId?: string) => {
    const user = MOCK_USERS.find(u => u.id === userId);
    return user ? user.avatar : 'https://picsum.photos/seed/placeholder/50';
