            <div key={community.id} className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 p-6 flex flex-col hover:shadow-lg transition-all">
              <div className="flex items-center space-x-4 mb-4">
                <div className="w-12 h-12 rounded-xl bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-2xl shadow-inner">
                  {community.icon}
                </div>
                <div>
                  <h3 className="font-bold text-slate-900 dark:text-white text-lg">{community.name}</h3>
                  <p className="text-xs text-slate-500 dark:text-slate-400">{community.memberCount} members • {community.projectCount} projects</p>
                </div>
              </div>
              <p className="text-slate-600 dark:text-slate-300 text-sm mb-6 flex-1 leading-relaxed line-clamp-2">
                {community.description}
              </p>
              <div className="flex flex-wrap gap-2 mb-6">
                {community.tags.map(tag => (
                  <span key={tag} className="text-[10px] bg-primary-50 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400 px-2 py-1 rounded-full font-bold uppercase tracking-wider">
                    #{tag}
                  </span>
                ))}
              </div>
              <button 
                onClick={() => onJoinCommunity(community)}
                className={`w-full py-2.5 rounded-xl font-bold transition-all ${
                  joinedIds.includes(community.id) 
                  ? 'bg-slate-100 dark:bg-slate-700 text-slate-500 cursor-default' 
                  : 'bg-primary-600 hover:bg-primary-500 text-white shadow-md hover:shadow-primary-600/20'
                }`}
                disabled={joinedIds.includes(community.id)}
              >
                {joinedIds.includes(community.id) ? 'Joined' : 'Join Community'}
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

