            <span className="text-sm font-bold capitalize">{view.replace('-', ' ')}</span>
          </div>
          <button 
            onClick={() => setDarkMode(!darkMode)}
            className="p-2 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white transition-all"
          >
            {darkMode ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
            )}
          </button>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && <Home onOpenExplore={() => setView('explore')} joinedCount={joinedCommunityIds.length} />}

          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={handlePreviewCommunity} />}

          {view === 'community-preview' && previewCommunity && (
            <CommunityDashboard 
              community={previewCommunity} 
              onJoin={() => handleJoinCommunity(previewCommunity.id)} 
              isJoined={joinedCommunityIds.includes(previewCommunity.id)}
            />
          )}

          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel 
                community={activeCommunity} 
                activeChannelId={activeChannelId}
                onSelectChannel={setActiveChannelId}
                onStartProject={() => {}} 
              />
              <ProjectView project={currentProject} currentUserId="u1" />
            </>
          )}

          {view === 'profile' && <Profile user={MOCK_USERS[0]} onLogout={handleLogout} />}
        </main>
      </div>
    </div>
  );
};

export default App;

