const MemberSidebar: React.FC<MemberSidebarProps> = ({ community }) => {
  const getRole = (roleId: string) => community.roles.find(r => r.id === roleId);
  const getMembersInRole = (roleId: string) => community.members.filter(m => m.roleId === roleId);

  return (
