import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Role } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview'>('home');
  const [darkMode, setDarkMode] = useState(false);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);

  // Dynamic Data State
  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  // Chat State
  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Welcome to OpenSource Innovators! Use #showcase to link your projects.', timestamp: '10:05 AM' },
      { id: '2', senderId: 'u3', senderName: 'Jordan Smith', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Jordan', content: 'Anyone up for a PR review on the documentation repo?', timestamp: '11:30 AM' }
    ]
  });

  // Modal State
  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', tagline: '', description: '' });

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.add('light');
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const joinedCommunities = communities.filter(c => joinedCommunityIds.includes(c.id));
  const activeCommunity = communities.find(c => c.id === activeCommunityId) || null;
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);

  // Get active projects for the current community
  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const currentProject = communityProjects[0] || projects[0];

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handlePreviewCommunity = (community: Community) => {
    setPreviewCommunity(community);
    setView('community-preview');
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  const handleCreateCommunity = () => {
    if (!newCommunityData.name) return;
    const id = `c${Date.now()}`;
    const newCommunity: Community = {
      id,
      name: newCommunityData.name,
      description: newCommunityData.description,
      icon: '🚀',
      memberCount: 1,
      projectCount: 0,
      tags: ['new', 'student-led'],
      createdBy: currentUser.id,
      roles: [
        { id: 'r1', name: 'Maintainer', color: 'text-rose-500' },
        { id: 'r2', name: 'Contributor', color: 'text-indigo-500' }
      ],
      members: [{ userId: currentUser.id, roleId: 'r1' }],
      channels: [
        { id: `ch_g_${id}`, name: 'general', type: 'chat' },
        { id: `ch_p_${id}`, name: 'project-spaces', type: 'project-list' }
      ]
    };
    setCommunities(prev => [...prev, newCommunity]);
    setJoinedCommunityIds(prev => [...prev, id]);
    setIsCreatingCommunity(false);
    setNewCommunityData({ name: '', tagline: '', description: '' });
    handleSelectCommunity(id);
  };

  const handleCreateProject = (projectData: { name: string, description: string, roles: string[] }) => {
    if (!activeCommunityId || !projectData.name) return;
    const newProject: Project = {
      id: `p${Date.now()}`,
      name: projectData.name,
      description: projectData.description,
      communityId: activeCommunityId,
      status: 'Proposed',
      techStack: ['React', 'Node.js'],
      contributors: [currentUser.id],
      rolesNeeded: projectData.roles,
      tasks: []
    };
    setProjects(prev => [...prev, newProject]);
    // Optionally auto-select the new project if we had a multi-project view
  };

  // --- RENDERING LOGIC ---

  if (isLanding) {
    return (
      <div className="min-h-screen bg-white dark:bg-slate-900 flex flex-col items-center justify-center p-6 text-center">
        <div className="max-w-5xl space-y-10 animate-in fade-in zoom-in duration-700">
          <div className="flex flex-col items-center space-y-6">
             <div className="w-20 h-20 bg-primary-600 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-primary-600/30">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
             </div>
             <h1 className="text-7xl font-black text-slate-900 dark:text-white tracking-tighter uppercase italic">NEXORA</h1>
          </div>
          <div className="space-y-6">
            <h2 className="text-4xl md:text-5xl font-black text-slate-800 dark:text-slate-100">The Collaboration Engine for Students.</h2>
            <p className="text-xl text-slate-500 dark:text-slate-400 max-w-3xl mx-auto leading-relaxed font-medium">
              Join elite student communities, build cross-disciplinary projects, and transition from learning to <span className="text-primary-600 dark:text-primary-400">building</span>.
            </p>
          </div>
          <div className="flex flex-col sm:flex-row items-center justify-center gap-6 pt-10">
            <button 
              onClick={() => { setIsLanding(false); setIsAuthView(true); }}
              className="px-12 py-5 bg-primary-600 text-white rounded-3xl font-black text-xl hover:bg-primary-500 transition-all shadow-2xl shadow-primary-600/30 active:scale-95"
            >
              Get Started
            </button>
            <button 
              onClick={() => { setIsLanding(false); setView('explore'); }}
              className="px-12 py-5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-3xl font-black text-xl hover:bg-slate-50 dark:hover:bg-slate-700 transition-all shadow-xl shadow-slate-200/50 dark:shadow-none active:scale-95"
            >
              Explore Spaces
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (isAuthView) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-6">
        <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-2xl w-full max-w-md border border-slate-200 dark:border-slate-800 animate-in slide-in-from-bottom-4 duration-500">
          <h2 className="text-3xl font-black mb-2 uppercase tracking-tight">Create Account</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium">Join thousands of students building the future.</p>
          <div className="space-y-4">
            <button 
              onClick={() => setIsAuthView(false)}
              className="w-full py-4 border border-slate-200 dark:border-slate-700 rounded-2xl font-bold flex items-center justify-center space-x-3 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all"
            >
              <img src="https://www.google.com/favicon.ico" className="w-5 h-5" alt="Google" />
              <span>Continue with Google</span>
            </button>
            <div className="flex items-center space-x-3 my-6">
              <div className="flex-1 h-[1px] bg-slate-200 dark:bg-slate-800" />
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">or email</span>
              <div className="flex-1 h-[1px] bg-slate-200 dark:bg-slate-800" />
            </div>
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Full Name</label>
              <input type="text" defaultValue="Alex Rivers" className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-primary-500 text-sm font-bold" />
            </div>
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Email Address</label>
              <input type="email" defaultValue="alex@mit-pune.edu" className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-primary-500 text-sm font-bold" />
            </div>
            <button 
              onClick={() => setIsAuthView(false)}
              className="w-full py-4 bg-primary-600 text-white rounded-2xl font-black text-lg hover:bg-primary-500 transition-all shadow-2xl shadow-primary-600/30 mt-4 active:scale-95"
            >
              Get Started
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-white dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100">
      {/* Creation Modal */}
      {isCreatingCommunity && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsCreatingCommunity(false)} />
          <div className="relative bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-2xl w-full max-w-xl animate-in zoom-in duration-300 border border-slate-200 dark:border-slate-800">
             <h2 className="text-3xl font-black mb-6 uppercase tracking-tight">Create a Community</h2>
             <div className="space-y-6">
                <div className="flex space-x-6">
                  <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-3xl flex items-center justify-center text-4xl shadow-inner cursor-pointer hover:bg-slate-200 transition-all">🚀</div>
                  <div className="flex-1 space-y-4">
                    <input 
                      type="text" 
                      placeholder="Community Name" 
                      className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 font-bold"
                      value={newCommunityData.name}
                      onChange={e => setNewCommunityData(p => ({ ...p, name: e.target.value }))}
                    />
                    <input 
                      type="text" 
                      placeholder="Short Tagline (e.g. Build fast, break things)" 
                      className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 text-sm"
                      value={newCommunityData.tagline}
                      onChange={e => setNewCommunityData(p => ({ ...p, tagline: e.target.value }))}
                    />
                  </div>
                </div>
                <textarea 
                  placeholder="Tell students what this community is for..." 
                  className="w-full bg-slate-50 dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 min-h-[120px] text-sm"
                  value={newCommunityData.description}
                  onChange={e => setNewCommunityData(p => ({ ...p, description: e.target.value }))}
                />
                <div className="flex gap-4">
                   <button onClick={() => setIsCreatingCommunity(false)} className="flex-1 py-4 font-bold rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all uppercase tracking-widest text-[10px]">Cancel</button>
                   <button 
                    onClick={handleCreateCommunity}
                    className="flex-[2] px-10 py-4 bg-primary-600 text-white rounded-2xl font-black shadow-lg hover:bg-primary-500 transition-all active:scale-95 uppercase tracking-widest text-xs"
                   >
                     Launch Community
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      <Sidebar 
        activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} 
        joinedCommunities={joinedCommunities}
        onSelectCommunity={handleSelectCommunity} 
        onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }}
        onOpenProfile={() => { setView('profile'); setActiveCommunityId(null); }}
        onOpenHome={() => { setView('home'); setActiveCommunityId(null); }}
        onCreateCommunity={() => setIsCreatingCommunity(true)}
      />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-16 flex items-center justify-between px-8 border-b border-slate-100 dark:border-slate-900 bg-white/80 dark:bg-slate-950/80 backdrop-blur-md z-10 flex-shrink-0">
          <div className="flex items-center space-x-2">
            <span className="text-slate-400 font-medium">/</span>
            <span className="text-sm font-black uppercase tracking-widest">{view.replace('-', ' ')}</span>
            {activeCommunity && (
              <>
                <span className="text-slate-300">/</span>
                <span className="text-sm font-black uppercase tracking-widest text-primary-600">{activeCommunity.name}</span>
              </>
            )}
          </div>
          <button 
            onClick={() => setDarkMode(!darkMode)}
            className="p-3 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white transition-all shadow-sm"
          >
            {darkMode ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
            )}
          </button>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && <Home onOpenExplore={() => setView('explore')} joinedCount={joinedCommunityIds.length} currentUser={currentUser} onCreateCommunity={() => setIsCreatingCommunity(true)} />}

          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={handlePreviewCommunity} />}

          {view === 'community-preview' && previewCommunity && (
            <CommunityDashboard 
              community={previewCommunity} 
              onJoin={() => handleJoinCommunity(previewCommunity.id)} 
              isJoined={joinedCommunityIds.includes(previewCommunity.id)}
              projects={projects}
            />
          )}

          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel 
                community={activeCommunity} 
                activeChannelId={activeChannelId}
                onSelectChannel={setActiveChannelId}
                onStartProject={() => {
                  // We can force the view to 'project-spaces' then open modal
                  const projectChannel = activeCommunity.channels.find(c => c.type === 'project-list');
                  if (projectChannel) setActiveChannelId(projectChannel.id);
                }} 
              />
              <div className="flex-1 flex overflow-hidden">
                {activeChannel?.type === 'chat' ? (
                  <div className="flex-1 p-8 bg-slate-50 dark:bg-slate-950 flex flex-col">
                    <ChatWindow 
                      messages={channelMessages[activeChannelId!] || []} 
                      onSendMessage={handleSendMessage} 
                      currentUser={currentUser}
                      placeholder={`Message # ${activeChannel.name}...`}
                    />
                  </div>
                ) : (
                  <ProjectView project={currentProject} currentUserId={currentUser.id} onCreateProject={handleCreateProject} />
                )}
                <MemberSidebar community={activeCommunity} />
              </div>
            </>
          )}

          {view === 'profile' && <Profile user={currentUser} onLogout={handleLogout} />}
        </main>
      </div>
    </div>
  );
};

export default App;

