          >
            <span className="text-lg">{community.icon}</span>
            <div className="absolute left-14 bg-slate-800 text-white text-[10px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap z-50 pointer-events-none shadow-xl">
              {community.name}
            </div>
          </button>
        ))}

        {/* Create Community Trigger */}
        <button 
          onClick={onCreateCommunity}
          className="w-12 h-12 rounded-xl flex items-center justify-center border-2 border-dashed border-slate-300 dark:border-slate-700 text-slate-400 hover:border-accent-500 hover:text-accent-500 transition-all hover:bg-accent-50/50 dark:hover:bg-accent-900/10"
