  onOpenExplore: () => void;
  joinedCount: number;
  currentUser: User;
  onCreateCommunity: () => void;
}

const Home: React.FC<HomeProps> = ({ onOpenExplore, joinedCount, currentUser, onCreateCommunity }) => {
  const [activeDmId, setActiveDmId] = useState<string | null>(null);
  const [dmHistory, setDmHistory] = useState<Record<string, ChatMessage[]>>({
    'dm1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Hey Alex, did you see the new mockups?', timestamp: '2:15 PM' },
      { id: '2', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'The new designs for Nexora are ready for review!', timestamp: '2:16 PM' }
    ]
  });

  const activeDm = MOCK_DMS.find(dm => dm.id === activeDmId);

