            </p>
            <div className="flex flex-col sm:flex-row gap-4 w-full max-w-md">
              <button 
                onClick={onOpenExplore}
                className="flex-1 px-8 py-4 bg-primary-600 text-white rounded-2xl font-bold shadow-lg shadow-primary-600/20 hover:bg-primary-500 transition-all hover:scale-105 active:scale-95"
              >
                Explore Communities
              </button>
              <button 
                onClick={onCreateCommunity}
                className="flex-1 px-8 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl font-bold hover:bg-slate-50 dark:hover:bg-slate-700 transition-all active:scale-95"
              >
                Create Space
              </button>
            </div>
