                  <button onClick={() => setActiveDmId(null)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-xl">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                    </svg>
                  </button>
                  <img src={activeDm?.senderAvatar} className="w-10 h-10 rounded-xl" alt="" />
                  <h3 className="font-black text-xl">{activeDm?.senderName}</h3>
               </div>
               <div className="flex space-x-2">
                 <button className="p-2 text-slate-400 hover:text-primary-600"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg></button>
                 <button className="p-2 text-slate-400 hover:text-primary-600"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg></button>
               </div>
             </div>
             <ChatWindow 
              messages={dmHistory[activeDmId] || []} 
              onSendMessage={handleSendMessage} 
              currentUser={currentUser}
              placeholder={`Message ${activeDm?.senderName}...`}
             />
