          <h3 className="font-bold text-slate-900 dark:text-white uppercase tracking-widest text-xs">Direct Messages</h3>
          <button className="text-slate-400 hover:text-primary-600">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {MOCK_DMS.map((dm) => (
            <button 
              key={dm.id} 
              onClick={() => setActiveDmId(dm.id)}
              className={`w-full p-4 flex items-start space-x-3 transition-all border-b border-slate-50 dark:border-slate-800 group text-left ${activeDmId === dm.id ? 'bg-primary-50 dark:bg-primary-900/20' : 'hover:bg-slate-50 dark:hover:bg-slate-800'}`}
            >
              <div className="relative">
                <img src={dm.senderAvatar} className="w-10 h-10 rounded-xl" alt={dm.senderName} />
                <div className={`absolute -bottom-1 -right-1 w-3 h-3 border-2 border-white dark:border-slate-900 rounded-full ${dm.unread ? 'bg-primary-600' : 'bg-slate-300 dark:bg-slate-600'}`} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-baseline mb-1">
                  <span className={`text-sm font-bold truncate ${dm.unread ? 'text-slate-900 dark:text-white' : 'text-slate-600 dark:text-slate-400'}`}>
                    {dm.senderName}
                  </span>
                  <span className="text-[10px] text-slate-400 font-medium flex-shrink-0 ml-2">{dm.timestamp}</span>
                </div>
                <p className={`text-xs truncate ${dm.unread ? 'text-slate-600 dark:text-slate-300 font-medium' : 'text-slate-400 dark:text-slate-500'}`}>
                  {dm.lastMessage}
                </p>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

