import React, { useState } from 'react';
import { Project, Task, ChatMessage } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onCreateProject: (data: { name: string, description: string, roles: string[] }) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onCreateProject }) => {
  const isMember = project.contributors.includes(currentUserId);
  const [activeTab, setActiveTab] = useState<'board' | 'discussions' | 'overview'>('overview');
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });

  const getTasksByStatus = (status: Task['status']) => project.tasks.filter(t => t.status === status);

  const handleSendMessage = (content: string) => {
    const user = MOCK_USERS.find(u => u.id === currentUserId);
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUserId,
      senderName: user?.name || 'User',
      senderAvatar: user?.avatar || '',
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleCreate = () => {
    onCreateProject({
      name: newProjectData.name,
      description: newProjectData.description,
      roles: newProjectData.roles.split(',').map(r => r.trim()).filter(r => !!r)
    });
    setIsCreatingProject(false);
    setNewProjectData({ name: '', description: '', roles: '' });
  };

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 overflow-hidden">
      {/* Create Project Modal */}
      {isCreatingProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsCreatingProject(false)} />
          <div className="relative bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-2xl w-full max-w-xl animate-in zoom-in duration-300 border border-slate-200 dark:border-slate-800">
             <h2 className="text-3xl font-black mb-6 uppercase tracking-tight">Create a Project Space</h2>
             <div className="space-y-6">
                <input 
                  type="text" 
                  placeholder="Project Name" 
                  className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 font-bold"
                  value={newProjectData.name}
                  onChange={e => setNewProjectData(p => ({ ...p, name: e.target.value }))}
                />
                <textarea 
                  placeholder="What are you building? Explain the goal and tech stack..." 
                  className="w-full bg-slate-50 dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 min-h-[120px] text-sm"
                  value={newProjectData.description}
                  onChange={e => setNewProjectData(p => ({ ...p, description: e.target.value }))}
                />
                <input 
                  type="text" 
                  placeholder="Roles needed (e.g. Designer, Backend, DevOps)" 
                  className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 text-sm"
                  value={newProjectData.roles}
                  onChange={e => setNewProjectData(p => ({ ...p, roles: e.target.value }))}
                />
                <div className="flex gap-4 pt-4">
                   <button onClick={() => setIsCreatingProject(false)} className="flex-1 py-4 font-bold rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all uppercase tracking-widest text-[10px]">Cancel</button>
                   <button 
                    onClick={handleCreate}
                    className="flex-[2] px-10 py-4 bg-primary-600 text-white rounded-2xl font-black shadow-lg hover:bg-primary-500 transition-all active:scale-95 uppercase tracking-widest text-xs"
                   >
                     Propose Project
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Project Header */}
      <div className="px-8 pt-8 pb-4 border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-start justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className="w-14 h-14 bg-primary-50 dark:bg-primary-900/30 rounded-2xl flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-sm border border-primary-100 dark:border-primary-800">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 dark:text-white uppercase tracking-tight">{project.name}</h2>
              <div className="flex items-center space-x-3 mt-1">
                <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-lg ${
                  project.status === 'Ongoing' ? 'bg-emerald-500 text-white' : 'bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400'
                }`}>
                  {project.status}
                </span>
                <span className="text-[10px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest">• {project.contributors.length} Contributors</span>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-3">
             <button 
                onClick={() => setIsCreatingProject(true)}
                className="px-6 py-3 border border-primary-600 text-primary-600 dark:text-primary-400 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-primary-50 dark:hover:bg-primary-900/20 transition-all active:scale-95"
             >
               New Project
             </button>
            {!isMember && (
              <button className="px-6 py-3 bg-primary-600 hover:bg-primary-500 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-lg shadow-primary-600/20 transition-all transform hover:-translate-y-0.5 active:scale-95">
                Join Space
              </button>
            )}
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex space-x-8">
          {['overview', 'board', 'discussions'].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab as any)}
              className={`pb-3 text-xs font-black uppercase tracking-widest border-b-2 transition-all ${
                activeTab === tab 
                  ? 'border-primary-600 text-primary-600' 
                  : 'border-transparent text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      {/* Main View Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar bg-slate-50 dark:bg-slate-900/50">
        {activeTab === 'overview' && (
          <div className="p-8 max-w-4xl space-y-8">
            <section>
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Description</h3>
              <p className="text-slate-600 dark:text-slate-300 leading-relaxed text-lg font-medium">
                {project.description}
              </p>
            </section>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <section>
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Roles Needed</h3>
                <div className="flex flex-wrap gap-3">
                  {project.rolesNeeded?.map(role => (
                    <span key={role} className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 px-4 py-2 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-300 shadow-sm">
                      {role}
                    </span>
                  ))}
                  {(!project.rolesNeeded || project.rolesNeeded.length === 0) && <span className="text-xs text-slate-400 italic">None currently specified</span>}
                </div>
              </section>
              <section>
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Tech Stack</h3>
                <div className="flex flex-wrap gap-2">
                  {project.techStack.map(tech => (
                    <span key={tech} className="bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border border-primary-100 dark:border-primary-800">
                      {tech}
                    </span>
                  ))}
                </div>
              </section>
            </div>
          </div>
        )}

        {activeTab === 'board' && (
          <div className="p-8 flex space-x-6 overflow-x-auto h-full">
            {isMember ? (
              ['todo', 'in-progress', 'done'].map((status) => (
                <div key={status} className="w-80 flex-shrink-0 flex flex-col">
                  <div className="flex items-center space-x-3 mb-4 px-2">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{status}</h4>
                    <span className="bg-slate-200 dark:bg-slate-800 text-slate-500 text-[10px] px-2 py-0.5 rounded-full font-bold">
                      {getTasksByStatus(status as any).length}
                    </span>
                  </div>
                  <div className="space-y-3 bg-white/50 dark:bg-slate-800/20 p-4 rounded-[2rem] flex-1 border border-slate-200 dark:border-slate-800">
                    {getTasksByStatus(status as any).map(task => (
                      <div key={task.id} className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 hover:shadow-md transition-all cursor-pointer">
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-200 mb-4">{task.title}</p>
                        {task.assignee && (
                          <div className="flex items-center space-x-2">
                            <div className="w-6 h-6 rounded-lg bg-primary-100 dark:bg-primary-900/30" />
                            <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Alex Rivers</span>
                          </div>
                        )}
                      </div>
                    ))}
                    <button className="w-full py-4 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-2xl text-slate-400 text-[10px] font-black tracking-widest hover:bg-white dark:hover:bg-slate-800 transition-all uppercase">
                      + Add Task
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-center py-20 opacity-30">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                </svg>
                <h3 className="text-xl font-black mb-2 uppercase tracking-tight">Project Board Locked</h3>
                <p className="text-sm">Join this project to access the task management system.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'discussions' && (
          <div className="h-full flex flex-col p-8">
            {isMember ? (
              <ChatWindow 
                messages={messages} 
                onSendMessage={handleSendMessage} 
                currentUser={MOCK_USERS.find(u => u.id === currentUserId)!}
                placeholder="Discuss project roadmap..."
              />
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-center py-20 opacity-30">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
                </svg>
                <h3 className="text-xl font-black mb-2 uppercase tracking-tight">Discussions Locked</h3>
                <p className="text-sm">Only project members can view and participate in discussions.</p>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

