                  placeholder="Project Name" 
                  className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 font-bold"
                  value={newProjectData.name}
                  onChange={e => setNewProjectData(p => ({ ...p, name: e.target.value }))}
                />
                <textarea 
                  placeholder="What are you building? Explain the goal and tech stack..." 
                  className="w-full bg-slate-50 dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 min-h-[120px] text-sm"
                  value={newProjectData.description}
