            <span className="text-slate-400 font-medium">/</span>
            <span className="text-sm font-black uppercase tracking-widest">{view.replace('-', ' ')}</span>
            {activeCommunity && (
              <>
                <span className="text-slate-300">/</span>
                <span className="text-sm font-black uppercase tracking-widest text-primary-600">{activeCommunity.name}</span>
              </>
            )}
