    setNewProjectData({ name: '', description: '', roles: '' });
    setNewProjectPhases(['Phase 1: Planning']);
  };

  const addPhaseInput = () => {
    setNewProjectPhases(prev => [...prev, `Phase ${prev.length + 1}: `]);
  };

