                <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-8 rounded-[2.5rem] flex items-center justify-between shadow-sm">
                   <div className="flex items-center space-x-6">
                      <div className="w-16 h-16 bg-slate-900 dark:bg-slate-800 rounded-3xl flex items-center justify-center text-white">
                        <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.43.372.823 1.102.823 2.222 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12"/></svg>
                      </div>
                      <div>
                         <p className="text-xl font-bold tracking-tight text-slate-900 dark:text-white">External Repository</p>
                         <a href={project.repositoryUrl} target="_blank" rel="noreferrer" className="text-sm text-primary-600 hover:underline font-medium">{project.repositoryUrl || 'No link provided'}</a>
                      </div>
                   </div>
                   <button className="px-6 py-3 bg-slate-100 dark:bg-slate-800 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all">Go to Repo</button>
                </div>
             </section>

             <section>
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-xl font-black uppercase tracking-tight">Releases & Versions</h3>
                </div>
                <div className="space-y-4">
                   <div className="p-6 bg-emerald-50 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-900/30 rounded-3xl flex items-center justify-between">
                      <div className="flex items-center space-x-6">
                         <span className="text-2xl font-black text-emerald-600">{project.currentVersion || 'v0.1.0'}</span>
                         <div>
                            <p className="font-bold text-slate-900 dark:text-white">Build Release</p>
                            <p className="text-xs text-slate-500">Live Production</p>
                         </div>
                      </div>
                      <span className="bg-emerald-500 text-white text-[10px] px-3 py-1 rounded-full font-black uppercase tracking-widest shadow-lg shadow-emerald-500/20">Active</span>
                   </div>
                </div>
             </section>
          </div>
        )}
      </div>
    </div>
  );
};

