                    <button onClick={addPhaseInput} className="text-[10px] font-black text-primary-600 uppercase tracking-widest hover:text-primary-500">+ Add Phase</button>
                  </div>
                </div>
                <div className="flex gap-4 pt-4">
                   <button onClick={() => setIsCreatingProject(false)} className="flex-1 py-4 font-bold rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all uppercase tracking-widest text-[10px]">Cancel</button>
                   <button onClick={handleLaunchProject} className="flex-[2] px-10 py-4 bg-primary-600 text-white rounded-2xl font-black shadow-lg hover:bg-primary-500 transition-all active:scale-95 uppercase tracking-widest text-xs">Launch Space</button>
