        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && <Home onOpenExplore={() => setView('explore')} joinedCount={joinedCommunityIds.length} currentUser={currentUser} onCreateCommunity={() => setIsCreatingCommunity(true)} />}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={handlePreviewCommunity} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden">
                {activeChannelId ? (
                  <div className="flex-1 p-8 bg-slate-50 dark:bg-slate-950 flex flex-col">
                    <ChatWindow messages={channelMessages[activeChannelId!] || []} onSendMessage={handleSendMessage} currentUser={currentUser} placeholder={`Message # ${activeChannel?.name || 'channel'}...`} />
                  </div>
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 uppercase font-black tracking-widest text-sm">Select a destination</div>
                )}
                <MemberSidebar community={activeCommunity} />
              </div>
            </>
          )}
          {view === 'profile' && <Profile user={currentUser} onLogout={handleLogout} />}
        </main>
      </div>
    </div>
  );
};

