import React from 'react';
import { Community, User, Role, Member } from '../types';
import { MOCK_USERS } from '../constants';

interface MemberSidebarProps {
  community: Community;
  projectMembers?: string[]; // Array of User IDs
}

const MemberSidebar: React.FC<MemberSidebarProps> = ({ community, projectMembers }) => {
  const getMembersInRole = (roleId: string) => {
    let members = community.members.filter(m => m.roleId === roleId);
    if (projectMembers) {
      members = members.filter(m => projectMembers.includes(m.userId));
    }
    return members;
  };

  const totalMemberCount = projectMembers ? projectMembers.length : community.memberCount;

  return (
    <div className="w-64 bg-slate-50 dark:bg-slate-900/50 border-l border-slate-200 dark:border-slate-800 flex flex-col flex-shrink-0 h-full">
      <div className="p-6 border-b border-slate-200 dark:border-slate-800">
        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">
          {projectMembers ? 'Project Members' : 'Community Members'} — {totalMemberCount}
        </h3>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-8 custom-scrollbar">
        {community.roles.map(role => {
          const members = getMembersInRole(role.id);
          if (members.length === 0) return null;
          return (
            <div key={role.id}>
              <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3 px-2">
                {role.name} — {members.length}
              </h4>
              <div className="space-y-1">
                {members.map(member => {
                  const user = MOCK_USERS.find(u => u.id === member.userId);
                  if (!user) return null;
                  return (
                    <button key={user.id} className="w-full flex items-center space-x-3 p-2 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all group text-left">
                      <div className="relative">
                        <img src={user.avatar} className="w-8 h-8 rounded-lg" alt={user.name} />
                        <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-emerald-500 border-2 border-slate-50 dark:border-slate-900 rounded-full" />
                      </div>
                      <span className={`text-sm font-bold truncate group-hover:text-primary-600 transition-colors ${role.color}`}>
                        {user.name}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
        {totalMemberCount === 0 && (
          <p className="p-4 text-center text-xs text-slate-400 italic">No members found.</p>
        )}
      </div>
    </div>
  );
};

