import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Milestone } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview'>('home');
  const [darkMode, setDarkMode] = useState(false);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);

  // Dynamic Data State
  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  // Chat State
  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Welcome to OpenSource Innovators! Use the project space to launch your ideas.', timestamp: '10:05 AM' },
    ]
  });

  // Modal States
  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', tagline: '', description: '' });

  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });
  const [newProjectMilestones, setNewProjectMilestones] = useState<string[]>(['Phase 1: Planning']);

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.add('light');
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const joinedCommunities = communities.filter(c => joinedCommunityIds.includes(c.id));
  const activeCommunity = communities.find(c => c.id === activeCommunityId) || null;
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);

  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const activeProject = projects.find(p => p.id === activeProjectId);

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  const handleCreateCommunity = () => {
    if (!newCommunityData.name) return;
    const id = `c${Date.now()}`;
    const newCommunity: Community = {
      id,
      name: newCommunityData.name,
      description: newCommunityData.description,
      icon: '🚀',
      memberCount: 1,
      projectCount: 0,
      tags: ['new'],
      createdBy: currentUser.id,
      roles: [
        { id: 'r1', name: 'Lead', color: 'text-rose-500' },
        { id: 'r2', name: 'Collaborator', color: 'text-indigo-500' }
      ],
      members: [{ userId: currentUser.id, roleId: 'r1' }],
      channels: [{ id: `ch_g_${id}`, name: 'general', type: 'chat' }]
    };
    setCommunities(prev => [...prev, newCommunity]);
    setJoinedCommunityIds(prev => [...prev, id]);
    setIsCreatingCommunity(false);
    setNewCommunityData({ name: '', tagline: '', description: '' });
    handleSelectCommunity(id);
  };

  const handleLaunchProject = () => {
    if (!activeCommunityId || !newProjectData.name) return;
    const newProjectId = `p${Date.now()}`;
    const newProject: Project = {
      id: newProjectId,
      name: newProjectData.name,
      description: newProjectData.description,
      communityId: activeCommunityId,
      status: 'Proposed',
      techStack: [],
      contributors: [currentUser.id],
      rolesNeeded: newProjectData.roles.split(',').map(r => r.trim()).filter(r => !!r),
      tasks: [],
      milestones: newProjectMilestones.filter(p => !!p.trim()).map((m, i) => ({
        id: `m-${i}-${newProjectId}`,
        title: m,
        description: '',
        dueDate: 'Pending',
        status: i === 0 ? 'active' : 'pending'
      })),
      currentVersion: 'v0.1.0',
      createdBy: currentUser.id
    };
    setProjects(prev => [...prev, newProject]);
    setActiveProjectId(newProjectId);
    setActiveChannelId(null);
    setIsCreatingProject(false);
    setNewProjectData({ name: '', description: '', roles: '' });
    setNewProjectMilestones(['Phase 1: Planning']);
  };

  const handleStartProject = (projectId: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, status: 'Ongoing' } : p));
  };

  const addMilestoneInput = () => {
    setNewProjectMilestones(prev => [...prev, `Phase ${prev.length + 1}: `]);
  };

  const updateMilestoneInput = (idx: number, val: string) => {
    const next = [...newProjectMilestones];
    next[idx] = val;
    setNewProjectMilestones(next);
  };

  // --- RENDERING ---

  if (isLanding) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center p-8">
        <div className="max-w-4xl text-center space-y-12 animate-in fade-in zoom-in duration-700">
           <div className="space-y-4">
              <div className="w-24 h-24 bg-primary-600 rounded-[2.5rem] mx-auto flex items-center justify-center shadow-2xl shadow-primary-600/30">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
              </div>
              <h1 className="text-8xl font-black text-slate-900 dark:text-white tracking-tighter uppercase italic">NEXORA</h1>
           </div>

           <div className="space-y-6">
              <h2 className="text-5xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight leading-tight">
                Where Students <span className="text-primary-600">Connect</span>, <span className="text-accent-600">Collaborate</span>, and <span className="text-indigo-600">Craft</span>.
              </h2>
              <p className="text-xl text-slate-500 dark:text-slate-400 max-w-2xl mx-auto leading-relaxed">
                The ultimate platform for student builders. Combine the networking of professional spaces with the execution power of version control.
              </p>
           </div>

           <div className="flex items-center justify-center gap-6 pt-8">
              <button 
                onClick={() => { setIsLanding(false); setIsAuthView(true); }}
                className="px-14 py-6 bg-primary-600 text-white rounded-3xl font-black text-xl hover:bg-primary-500 transition-all shadow-2xl shadow-primary-600/40 active:scale-95 uppercase tracking-widest"
              >
                Log In to Nexora
              </button>
              <button 
                onClick={() => { setIsLanding(false); setView('explore'); }}
                className="px-14 py-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-800 dark:text-white rounded-3xl font-black text-xl hover:bg-slate-50 dark:hover:bg-slate-800 transition-all shadow-xl active:scale-95 uppercase tracking-widest"
              >
                Explore
              </button>
           </div>

           <div className="pt-12 grid grid-cols-1 md:grid-cols-3 gap-8 text-left">
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                <h3 className="font-black uppercase tracking-widest text-xs text-primary-600 mb-2">Connect</h3>
                <p className="text-sm text-slate-500">Join interest-based student communities at your campus and beyond.</p>
              </div>
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                <h3 className="font-black uppercase tracking-widest text-xs text-accent-600 mb-2">Collab</h3>
                <p className="text-sm text-slate-500">Proposed ideas become reality. Start projects and find your team.</p>
              </div>
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                <h3 className="font-black uppercase tracking-widest text-xs text-indigo-600 mb-2">Craft</h3>
                <p className="text-sm text-slate-500">Manage milestones and track your technical growth as a builder.</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  if (isAuthView) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-6">
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl w-full max-w-md border border-slate-200 dark:border-slate-800 animate-in slide-in-from-bottom-8 duration-500">
          <h2 className="text-4xl font-black mb-2 uppercase tracking-tight">Nexora Auth</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-10 font-medium">Log in to your student collaborative space.</p>
          <div className="space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Full Name</label>
              <input type="text" defaultValue="Alex Rivers" className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-primary-500 text-sm font-bold" />
            </div>
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">University Email</label>
              <input type="email" defaultValue="alex@mit-pune.edu" className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-primary-500 text-sm font-bold" />
            </div>
            <button 
              onClick={() => setIsAuthView(false)}
              className="w-full py-5 bg-primary-600 text-white rounded-2xl font-black text-xl hover:bg-primary-500 transition-all shadow-2xl shadow-primary-600/30 mt-6 active:scale-95 uppercase tracking-widest"
            >
              Continue
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-white dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100">
      {/* Creation Modal (Community) */}
      {isCreatingCommunity && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsCreatingCommunity(false)} />
          <div className="relative bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-2xl w-full max-w-xl animate-in zoom-in duration-300 border border-slate-200 dark:border-slate-800">
             <h2 className="text-3xl font-black mb-6 uppercase tracking-tight">Create a Community</h2>
             <div className="space-y-6">
                <input type="text" placeholder="Community Name" className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 font-bold" value={newCommunityData.name} onChange={e => setNewCommunityData(p => ({ ...p, name: e.target.value }))} />
                <textarea placeholder="Tell students what this community is for..." className="w-full bg-slate-50 dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 min-h-[120px] text-sm" value={newCommunityData.description} onChange={e => setNewCommunityData(p => ({ ...p, description: e.target.value }))} />
                <div className="flex gap-4">
                   <button onClick={() => setIsCreatingCommunity(false)} className="flex-1 py-4 font-bold rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all uppercase tracking-widest text-[10px]">Cancel</button>
                   <button onClick={handleCreateCommunity} className="flex-[2] px-10 py-4 bg-primary-600 text-white rounded-2xl font-black shadow-lg hover:bg-primary-500 transition-all active:scale-95 uppercase tracking-widest text-xs">Launch Community</button>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Project Creation Modal */}
      {isCreatingProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsCreatingProject(false)} />
          <div className="relative bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-2xl w-full max-w-xl animate-in zoom-in duration-300 border border-slate-200 dark:border-slate-800 custom-scrollbar overflow-y-auto max-h-[90vh]">
             <h2 className="text-3xl font-black mb-6 uppercase tracking-tight">Launch Project Space</h2>
             <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block">Project Name</label>
                  <input type="text" placeholder="Name" className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 font-bold" value={newProjectData.name} onChange={e => setNewProjectData(p => ({ ...p, name: e.target.value }))} />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block">Define Execution Milestones</label>
                  <div className="space-y-2">
                    {newProjectMilestones.map((milestone, idx) => (
                      <input key={idx} type="text" placeholder={`Phase ${idx + 1}`} className="w-full bg-slate-50 dark:bg-slate-800 p-3 rounded-xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 text-sm" value={milestone} onChange={e => updateMilestoneInput(idx, e.target.value)} />
                    ))}
                    <button onClick={addMilestoneInput} className="text-[10px] font-black text-primary-600 uppercase tracking-widest hover:text-primary-500">+ Add Milestone</button>
                  </div>
                </div>
                <div className="flex gap-4 pt-4">
                   <button onClick={() => setIsCreatingProject(false)} className="flex-1 py-4 font-bold rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all uppercase tracking-widest text-[10px]">Cancel</button>
                   <button onClick={handleLaunchProject} className="flex-[2] px-10 py-4 bg-primary-600 text-white rounded-2xl font-black shadow-lg hover:bg-primary-500 transition-all active:scale-95 uppercase tracking-widest text-xs">Propose Project</button>
                </div>
             </div>
          </div>
        </div>
      )}

      <Sidebar activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} joinedCommunities={joinedCommunities} onSelectCommunity={handleSelectCommunity} onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }} onOpenProfile={() => { setView('profile'); setActiveCommunityId(null); }} onOpenHome={() => { setView('home'); setActiveCommunityId(null); }} onCreateCommunity={() => setIsCreatingCommunity(true)} />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-16 flex items-center justify-between px-8 border-b border-slate-100 dark:border-slate-900 bg-white/80 dark:bg-slate-950/80 backdrop-blur-md z-10 flex-shrink-0">
          <div className="flex items-center space-x-2"><span className="text-slate-400 font-medium">/</span><span className="text-sm font-black uppercase tracking-widest">{view.replace('-', ' ')}</span>{activeCommunity && (<><span className="text-slate-300">/</span><span className="text-sm font-black uppercase tracking-widest text-primary-600">{activeCommunity.name}</span></>)}</div>
          <button onClick={() => setDarkMode(!darkMode)} className="p-3 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white transition-all shadow-sm">{darkMode ? (<svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>) : (<svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>)}</button>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && <Home onOpenExplore={() => setView('explore')} joinedCount={joinedCommunityIds.length} currentUser={currentUser} onCreateCommunity={() => setIsCreatingCommunity(true)} />}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => setPreviewCommunity(community)} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden">
                {activeChannelId ? (
                  <div className="flex-1 p-8 bg-slate-50 dark:bg-slate-950 flex flex-col">
                    <ChatWindow messages={channelMessages[activeChannelId!] || []} onSendMessage={handleSendMessage} currentUser={currentUser} placeholder={`Message # ${activeChannel?.name || 'channel'}...`} />
                  </div>
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 uppercase font-black tracking-widest text-sm">Select a destination</div>
                )}
                <MemberSidebar 
                  community={activeCommunity} 
                  projectMembers={activeProject?.contributors} 
                />
              </div>
            </>
          )}
          {view === 'profile' && <Profile user={currentUser} onLogout={handleLogout} />}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Project, ChatMessage, Milestone } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onStartProject?: (id: string) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onStartProject }) => {
  const isMember = project.contributors.includes(currentUserId);
