import React from 'react';
import { Community, User, Role, Member } from '../types';
import { MOCK_USERS } from '../constants';

interface MemberSidebarProps {
  community: Community;
  projectMembers?: string[]; // Array of User IDs
}

const MemberSidebar: React.FC<MemberSidebarProps> = ({ community, projectMembers }) => {
  const getMembersInRole = (roleId: string) => {
    let members = community.members.filter(m => m.roleId === roleId);
    if (projectMembers) {
      // Filter the community member list to only those who are in the project
      members = members.filter(m => projectMembers.includes(m.userId));
    }
    return members;
  };

  const totalMemberCount = projectMembers ? projectMembers.length : community.memberCount;

  return (
    <div className="w-64 bg-slate-50 dark:bg-slate-900/50 border-l border-slate-200 dark:border-slate-800 flex flex-col flex-shrink-0 h-full">
      <div className="p-6 border-b border-slate-200 dark:border-slate-800">
        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">
          {projectMembers ? 'Space Contributors' : 'Community Members'} — {totalMemberCount}
        </h3>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-8 custom-scrollbar">
        {community.roles.map(role => {
          const members = getMembersInRole(role.id);
          if (members.length === 0) return null;
          return (
            <div key={role.id}>
              <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3 px-2">
                {role.name} — {members.length}
              </h4>
              <div className="space-y-1">
                {members.map(member => {
                  const user = MOCK_USERS.find(u => u.id === member.userId);
                  if (!user) return null;
                  return (
                    <button key={user.id} className="w-full flex items-center space-x-3 p-2 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all group text-left">
                      <div className="relative">
                        <img src={user.avatar} className="w-8 h-8 rounded-lg" alt={user.name} />
                        <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-emerald-500 border-2 border-slate-50 dark:border-slate-900 rounded-full" />
                      </div>
                      <span className={`text-sm font-bold truncate group-hover:text-primary-600 transition-colors ${role.color}`}>
                        {user.name}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
        {totalMemberCount === 0 && (
          <p className="p-4 text-center text-xs text-slate-400 italic">No contributors found in this context.</p>
        )}
      </div>
    </div>
  );
};

export default MemberSidebar;

export type ProjectStatus = 'Proposed' | 'Ongoing' | 'Completed';

export interface User {
  id: string;
  name: string;
  role: string;
  college: string;
  bio: string;
  avatar: string;
  skills: string[];
  githubUrl: string;
  linkedinUrl: string;
  reputation: number;
}

export interface Task {
  id: string;
  title: string;
  status: 'todo' | 'in-progress' | 'done';
  assignee?: string;
}

export interface ProjectResource {
  id: string;
  title: string;
  url: string;
  type: 'link' | 'doc' | 'repo';
}

export interface Milestone {
  id: string;
  title: string;
  description: string;
  dueDate: string;
  status: 'pending' | 'active' | 'completed';
}

export interface Project {
  id: string;
  name: string;
  description: string;
  communityId: string;
  status: ProjectStatus;
  techStack: string[];
  contributors: string[];
  tasks: Task[];
  milestones: Milestone[];
  resources: ProjectResource[];
  repositoryUrl?: string;
  currentVersion?: string;
  rolesNeeded?: string[];
  createdBy: string;
}

export interface Role {
  id: string;
  name: string;
  color: string;
}

export interface Member {
  userId: string;
  roleId: string;
}

export interface Community {
  id: string;
  name: string;
  description: string;
  icon: string;
  memberCount: number;
  projectCount: number;
  channels: Channel[];
  tags: string[];
  createdBy: string;
  roles: Role[];
  members: Member[];
}

export interface Channel {
  id: string;
  name: string;
  type: 'chat' | 'project-list';
}

export interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderAvatar: string;
  content: string;
  timestamp: string;
}

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Milestone } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview'>('home');
  const [darkMode, setDarkMode] = useState(false);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);

  // Dynamic Data State
  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  // Chat State
  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Welcome to OpenSource Innovators! Use the project space to launch your ideas.', timestamp: '10:05 AM' },
    ]
  });

  // Modal States
  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', tagline: '', description: '' });

  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });
  const [newProjectMilestones, setNewProjectMilestones] = useState<string[]>(['Phase 1: Concept']);

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.add('light');
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const joinedCommunities = communities.filter(c => joinedCommunityIds.includes(c.id));
  const activeCommunity = communities.find(c => c.id === activeCommunityId) || null;
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);

  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const activeProject = projects.find(p => p.id === activeProjectId);

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  const handleCreateCommunity = () => {
    if (!newCommunityData.name) return;
    const id = `c${Date.now()}`;
    const newCommunity: Community = {
      id,
      name: newCommunityData.name,
      description: newCommunityData.description,
      icon: '🚀',
      memberCount: 1,
      projectCount: 0,
      tags: ['new-community'],
      createdBy: currentUser.id,
      roles: [
        { id: 'r1', name: 'Maintainer', color: 'text-rose-500' },
        { id: 'r2', name: 'Contributor', color: 'text-indigo-500' }
      ],
      members: [{ userId: currentUser.id, roleId: 'r1' }],
      channels: [{ id: `ch_g_${id}`, name: 'general', type: 'chat' }]
    };
    setCommunities(prev => [...prev, newCommunity]);
    setJoinedCommunityIds(prev => [...prev, id]);
    setIsCreatingCommunity(false);
    setNewCommunityData({ name: '', tagline: '', description: '' });
    handleSelectCommunity(id);
  };

  const handleLaunchProject = () => {
    if (!activeCommunityId || !newProjectData.name) return;
    const newProjectId = `p${Date.now()}`;
    const newProject: Project = {
      id: newProjectId,
      name: newProjectData.name,
      description: newProjectData.description,
      communityId: activeCommunityId,
      status: 'Proposed',
      techStack: [],
      contributors: [currentUser.id],
      rolesNeeded: newProjectData.roles.split(',').map(r => r.trim()).filter(r => !!r),
      tasks: [],
      resources: [],
      milestones: newProjectMilestones.filter(m => !!m.trim()).map((m, i) => ({
        id: `m-${i}-${newProjectId}`,
        title: m,
        description: '',
        dueDate: 'TBD',
        status: i === 0 ? 'active' : 'pending'
      })),
      currentVersion: 'v0.0.1',
      createdBy: currentUser.id
    };
    setProjects(prev => [...prev, newProject]);
    setActiveProjectId(newProjectId);
    setActiveChannelId(null);
    setIsCreatingProject(false);
    setNewProjectData({ name: '', description: '', roles: '' });
    setNewProjectMilestones(['Phase 1: Concept']);
  };

  const handleStartProject = (projectId: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, status: 'Ongoing' } : p));
  };

  const handleAddResource = (projectId: string, title: string, url: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id === projectId) {
        return {
          ...p,
          resources: [...p.resources, { id: Date.now().toString(), title, url, type: 'link' }]
        };
      }
      return p;
    }));
  };

  const addMilestoneInput = () => {
    setNewProjectMilestones(prev => [...prev, `Phase ${prev.length + 1}: `]);
  };

  const updateMilestoneInput = (idx: number, val: string) => {
    const next = [...newProjectMilestones];
    next[idx] = val;
    setNewProjectMilestones(next);
  };

  if (isLanding) {
    return (
      <div className="min-h-screen bg-white dark:bg-slate-950 flex flex-col items-center justify-center p-12 text-center">
        <div className="max-w-4xl space-y-16 animate-in fade-in zoom-in duration-1000">
          <div className="flex flex-col items-center space-y-8">
             <div className="w-24 h-24 bg-primary-600 rounded-[2.8rem] flex items-center justify-center shadow-2xl shadow-primary-600/30 transform hover:rotate-12 transition-transform">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
             </div>
             <div className="space-y-4">
                <h1 className="text-8xl font-black text-slate-900 dark:text-white tracking-tighter uppercase italic">NEXORA</h1>
                <p className="text-2xl font-bold text-primary-600 uppercase tracking-[0.2em]">Connect. Collab. Craft.</p>
             </div>
          </div>

          <div className="space-y-6">
            <h2 className="text-5xl md:text-6xl font-black text-slate-800 dark:text-slate-100 leading-tight">
              The Social Engine for <span className="text-primary-600">Student Builders</span>.
            </h2>
            <p className="text-xl text-slate-500 dark:text-slate-400 max-w-2xl mx-auto leading-relaxed font-medium">
              Combine the networking of professional spaces with the execution power of GitHub. Join elite student communities and transition from dreaming to building.
            </p>
          </div>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-6 pt-6">
            <button 
              onClick={() => { setIsLanding(false); setIsAuthView(true); }} 
              className="px-16 py-6 bg-primary-600 text-white rounded-[2rem] font-black text-xl hover:bg-primary-500 transition-all shadow-2xl shadow-primary-600/40 active:scale-95 uppercase tracking-widest"
            >
              Sign In to Nexora
            </button>
            <button 
              onClick={() => { setIsLanding(false); setView('explore'); }} 
              className="px-16 py-6 bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 text-slate-800 dark:text-white rounded-[2rem] font-black text-xl hover:bg-slate-50 dark:hover:bg-slate-800 transition-all active:scale-95 uppercase tracking-widest shadow-xl"
            >
              Explore Space
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (isAuthView) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-6">
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl w-full max-w-md border border-slate-200 dark:border-slate-800 animate-in slide-in-from-bottom-12 duration-500">
          <h2 className="text-4xl font-black mb-2 uppercase tracking-tight">Nexora Auth</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-10 font-medium">Join the next wave of collaborative builders.</p>
          <div className="space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">University Email</label>
              <input type="email" defaultValue="alex@mit-pune.edu" className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-primary-500 text-sm font-bold" />
            </div>
            <button 
              onClick={() => setIsAuthView(false)} 
              className="w-full py-5 bg-primary-600 text-white rounded-2xl font-black text-xl hover:bg-primary-500 transition-all shadow-2xl shadow-primary-600/30 mt-6 active:scale-95 uppercase tracking-widest"
            >
              Enter Space
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-white dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100">
      {/* Creation Modal (Community) */}
      {isCreatingCommunity && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsCreatingCommunity(false)} />
          <div className="relative bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-2xl w-full max-w-xl animate-in zoom-in duration-300 border border-slate-200 dark:border-slate-800">
             <h2 className="text-3xl font-black mb-6 uppercase tracking-tight">Create a Community</h2>
             <div className="space-y-6">
                <input type="text" placeholder="Community Name" className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 font-bold" value={newCommunityData.name} onChange={e => setNewCommunityData(p => ({ ...p, name: e.target.value }))} />
                <textarea placeholder="Tell students what this community is for..." className="w-full bg-slate-50 dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 min-h-[120px] text-sm" value={newCommunityData.description} onChange={e => setNewCommunityData(p => ({ ...p, description: e.target.value }))} />
                <div className="flex gap-4">
                   <button onClick={() => setIsCreatingCommunity(false)} className="flex-1 py-4 font-bold rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all uppercase tracking-widest text-[10px]">Cancel</button>
                   <button onClick={handleCreateCommunity} className="flex-[2] px-10 py-4 bg-primary-600 text-white rounded-2xl font-black shadow-lg hover:bg-primary-500 transition-all active:scale-95 uppercase tracking-widest text-xs">Launch Space</button>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Project Proposal Modal */}
      {isCreatingProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsCreatingProject(false)} />
          <div className="relative bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-2xl w-full max-w-xl animate-in zoom-in duration-300 border border-slate-200 dark:border-slate-800 custom-scrollbar overflow-y-auto max-h-[90vh]">
             <h2 className="text-3xl font-black mb-6 uppercase tracking-tight">Propose Project</h2>
             <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block px-1">Project Name</label>
                  <input type="text" placeholder="Name" className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 font-bold" value={newProjectData.name} onChange={e => setNewProjectData(p => ({ ...p, name: e.target.value }))} />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block px-1">Define Execution Milestones</label>
                  <div className="space-y-2">
                    {newProjectMilestones.map((milestone, idx) => (
                      <input key={idx} type="text" placeholder={`Milestone ${idx + 1}`} className="w-full bg-slate-50 dark:bg-slate-800 p-3 rounded-xl border border-slate-100 dark:border-slate-800 outline-none focus:ring-2 focus:ring-primary-500 text-sm" value={milestone} onChange={e => updateMilestoneInput(idx, e.target.value)} />
                    ))}
                    <button onClick={addMilestoneInput} className="text-[10px] font-black text-primary-600 uppercase tracking-widest hover:text-primary-500 px-1">+ Add Milestone</button>
                  </div>
                </div>
                <div className="flex gap-4 pt-4">
                   <button onClick={() => setIsCreatingProject(false)} className="flex-1 py-4 font-bold rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all uppercase tracking-widest text-[10px]">Cancel</button>
                   <button onClick={handleLaunchProject} className="flex-[2] px-10 py-4 bg-primary-600 text-white rounded-2xl font-black shadow-lg hover:bg-primary-500 transition-all active:scale-95 uppercase tracking-widest text-xs">Submit Proposal</button>
                </div>
             </div>
          </div>
        </div>
      )}

      <Sidebar activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} joinedCommunities={joinedCommunities} onSelectCommunity={handleSelectCommunity} onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }} onOpenProfile={() => { setView('profile'); setActiveCommunityId(null); }} onOpenHome={() => { setView('home'); setActiveCommunityId(null); }} onCreateCommunity={() => setIsCreatingCommunity(true)} />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-16 flex items-center justify-between px-8 border-b border-slate-100 dark:border-slate-900 bg-white/80 dark:bg-slate-950/80 backdrop-blur-md z-10 flex-shrink-0">
          <div className="flex items-center space-x-2"><span className="text-slate-400 font-medium">/</span><span className="text-sm font-black uppercase tracking-widest">{view.replace('-', ' ')}</span>{activeCommunity && (<><span className="text-slate-300">/</span><span className="text-sm font-black uppercase tracking-widest text-primary-600">{activeCommunity.name}</span></>)}</div>
          <button onClick={() => setDarkMode(!darkMode)} className="p-3 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white transition-all shadow-sm">{darkMode ? (<svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>) : (<svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>)}</button>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && <Home onOpenExplore={() => setView('explore')} joinedCount={joinedCommunityIds.length} currentUser={currentUser} onCreateCommunity={() => setIsCreatingCommunity(true)} />}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => setPreviewCommunity(community)} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden">
                {activeChannelId ? (
                  <div className="flex-1 p-8 bg-slate-50 dark:bg-slate-950 flex flex-col">
                    <ChatWindow messages={channelMessages[activeChannelId!] || []} onSendMessage={handleSendMessage} currentUser={currentUser} placeholder={`Message # ${activeChannel?.name || 'channel'}...`} />
                  </div>
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 uppercase font-black tracking-widest text-sm">Select a destination</div>
                )}
                {/* Filter member sidebar to only show project members if inside a project view */}
                <MemberSidebar 
                  community={activeCommunity} 
                  projectMembers={activeProject?.contributors}
                />
              </div>
            </>
          )}
          {view === 'profile' && <Profile user={currentUser} onLogout={handleLogout} />}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Project, ChatMessage, Milestone, ProjectResource } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onStartProject?: (id: string) => void;
  onAddResource?: (projectId: string, title: string, url: string) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onStartProject, onAddResource }) => {
  const isMember = project.contributors.includes(currentUserId);
  const isCreator = project.createdBy === currentUserId;
  const [activeTab, setActiveTab] = useState<'overview' | 'milestones' | 'discussions' | 'resources'>('overview');
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  // New resource state
  const [resTitle, setResTitle] = useState('');
  const [resUrl, setResUrl] = useState('');

  const handleSendMessage = (content: string) => {
    const user = MOCK_USERS.find(u => u.id === currentUserId);
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUserId,
      senderName: user?.name || 'User',
      senderAvatar: user?.avatar || '',
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleAddRes = (e: React.FormEvent) => {
    e.preventDefault();
    if (resTitle && resUrl && onAddResource) {
      onAddResource(project.id, resTitle, resUrl);
      setResTitle('');
      setResUrl('');
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 overflow-hidden">
      {/* Project Header */}
      <div className="px-8 pt-8 pb-4 border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-start justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className="w-14 h-14 bg-primary-50 dark:bg-primary-900/30 rounded-2xl flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-sm border border-primary-100 dark:border-primary-800">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 dark:text-white uppercase tracking-tight">{project.name}</h2>
              <div className="flex items-center space-x-3 mt-1">
                <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-lg ${
                  project.status === 'Ongoing' ? 'bg-emerald-500 text-white' : 
                  project.status === 'Proposed' ? 'bg-amber-500 text-white' :
                  'bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400'
                }`}>
                  {project.status}
                </span>
                <span className="text-[10px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest">• {project.contributors.length} Team Members</span>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            {project.status === 'Proposed' && isCreator && (
              <button 
                onClick={() => onStartProject?.(project.id)}
                className="px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-lg shadow-emerald-600/20 transition-all active:scale-95"
              >
                Officially Start Project
              </button>
            )}
            {!isMember && (
              <button className="px-6 py-3 bg-primary-600 hover:bg-primary-500 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-lg shadow-primary-600/20 transition-all active:scale-95">
                Join Space
              </button>
            )}
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex space-x-8">
          {['overview', 'milestones', 'discussions', 'resources'].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab as any)}
              className={`pb-3 text-xs font-black uppercase tracking-widest border-b-2 transition-all ${
                activeTab === tab 
                  ? 'border-primary-600 text-primary-600' 
                  : 'border-transparent text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar bg-slate-50 dark:bg-slate-900/50">
        {activeTab === 'overview' && (
          <div className="p-8 max-w-4xl space-y-8 animate-in fade-in duration-300">
            <section>
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Goal & Objective</h3>
              <p className="text-slate-600 dark:text-slate-300 leading-relaxed text-lg font-medium">
                {project.description}
              </p>
            </section>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <section>
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Roles Needed</h3>
                <div className="flex flex-wrap gap-3">
                  {project.rolesNeeded?.map(role => (
                    <span key={role} className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 px-4 py-2 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-300 shadow-sm">
                      {role}
                    </span>
                  ))}
                  {(!project.rolesNeeded || project.rolesNeeded.length === 0) && <span className="text-xs text-slate-400 italic">No specific roles requested.</span>}
                </div>
              </section>
            </div>
          </div>
        )}

        {activeTab === 'milestones' && (
          <div className="p-8 max-w-3xl mx-auto animate-in zoom-in duration-300">
             <div className="flex items-center justify-between mb-10">
                <h3 className="text-xl font-black uppercase tracking-tight">Execution Milestones</h3>
             </div>

             <div className="relative space-y-8 before:absolute before:inset-0 before:ml-5 before:-translate-x-px before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-slate-200 dark:before:via-slate-800 before:to-transparent">
                {project.milestones && project.milestones.map((m, idx) => (
                  <div key={m.id} className="relative flex items-center justify-between group">
                    <div className="flex items-center space-x-8">
                       <div className={`flex items-center justify-center w-10 h-10 rounded-full border-4 border-white dark:border-slate-950 shadow-xl z-10 transition-all ${
                         m.status === 'completed' ? 'bg-emerald-500 text-white' :
                         m.status === 'active' ? 'bg-primary-600 text-white scale-110' : 'bg-slate-200 dark:bg-slate-800 text-slate-400'
                       }`}>
                         {m.status === 'completed' ? (
                           <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                         ) : <span>{idx + 1}</span>}
                       </div>
                       <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 min-w-[300px] shadow-sm group-hover:shadow-md transition-all">
                          <p className={`font-black uppercase tracking-widest text-xs ${m.status === 'active' ? 'text-primary-600' : 'text-slate-500'}`}>{m.title}</p>
                          <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-tighter">Status: {m.status}</p>
                       </div>
                    </div>
                  </div>
                ))}
                {(!project.milestones || project.milestones.length === 0) && (
                   <p className="text-slate-400 italic text-sm">No milestones defined.</p>
                )}
             </div>
          </div>
        )}

        {activeTab === 'discussions' && (
          <div className="h-full flex flex-col p-8 animate-in fade-in duration-300">
            {isMember ? (
              <ChatWindow 
                messages={messages} 
                onSendMessage={handleSendMessage} 
                currentUser={MOCK_USERS.find(u => u.id === currentUserId)!}
                placeholder="Team discussion for the current phase..."
              />
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-center py-20 opacity-30">
                <h3 className="text-xl font-black mb-2 uppercase tracking-tight">Access Locked</h3>
                <p className="text-sm">Join the project space to participate in internal team chats.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'resources' && (
          <div className="p-8 max-w-4xl space-y-12 animate-in zoom-in duration-300">
             <section>
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-xl font-black uppercase tracking-tight">Project Resources</h3>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-10">
                   {project.resources?.map(res => (
                     <a 
                       key={res.id} 
                       href={res.url} 
                       target="_blank" 
                       rel="noreferrer" 
                       className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-6 rounded-3xl hover:border-primary-500 transition-all flex items-center justify-between shadow-sm group"
                     >
                       <div className="flex items-center space-x-4">
                         <div className="w-10 h-10 bg-slate-50 dark:bg-slate-800 rounded-xl flex items-center justify-center text-slate-400 group-hover:text-primary-600">
                           <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" /></svg>
                         </div>
                         <div>
                            <p className="font-bold text-slate-800 dark:text-white truncate max-w-[150px]">{res.title}</p>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{res.type}</p>
                         </div>
                       </div>
                       <svg className="w-4 h-4 text-slate-300 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                     </a>
                   ))}
                </div>

                {isMember && (
                  <div className="bg-slate-100 dark:bg-slate-800/50 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-700">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-6">Add New Resource</h4>
                    <form onSubmit={handleAddRes} className="space-y-4">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <input 
                            type="text" 
                            placeholder="Resource Title (e.g. Documentation)" 
                            className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-primary-500 text-sm font-bold"
                            value={resTitle}
                            onChange={e => setResTitle(e.target.value)}
                          />
                          <input 
                            type="url" 
                            placeholder="https://..." 
                            className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-primary-500 text-sm"
                            value={resUrl}
                            onChange={e => setResUrl(e.target.value)}
                          />
                       </div>
                       <button 
                        type="submit"
                        className="w-full py-4 bg-primary-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-primary-600/20 hover:bg-primary-500 transition-all active:scale-95"
                       >
                         Save Resource
                       </button>
                    </form>
                  </div>
                )}
             </section>
          </div>
        )}
      </div>
    </div>
  );
};

