import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Milestone, ProjectResource } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview' | 'user-profile'>('home');
  const [darkMode, setDarkMode] = useState(false);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);

  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'The infrastructure setup for the new community is live. Check the #showcase channel.', timestamp: '10:05 AM' },
    ]
  });

  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', tagline: '', description: '' });
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });
  const [newProjectMilestones, setNewProjectMilestones] = useState<string[]>(['Setup Environment']);

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.add('light');
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const joinedCommunities = communities.filter(c => joinedCommunityIds.includes(c.id));
  const activeCommunity = communities.find(c => c.id === activeCommunityId) || null;
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);
  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const activeProject = projects.find(p => p.id === activeProjectId);

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
    setView('community');
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
    setView('community');
  };

  const handleViewProfile = (userId: string) => {
    setSelectedUserId(userId);
    setView('user-profile');
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  const handleCreateCommunity = () => {
    if (!newCommunityData.name) return;
    const id = `c${Date.now()}`;
    const newCommunity: Community = {
      id,
      name: newCommunityData.name,
      description: newCommunityData.description,
      icon: '🏛️',
      memberCount: 1,
      projectCount: 0,
      tags: ['new-community'],
      createdBy: currentUser.id,
      roles: [
        { id: 'r1', name: 'Admin', color: 'text-indigo-600' },
        { id: 'r2', name: 'Member', color: 'text-slate-500' }
      ],
      members: [{ userId: currentUser.id, roleId: 'r1' }],
      channels: [{ id: `ch_g_${id}`, name: 'general', type: 'chat' }]
    };
    setCommunities(prev => [...prev, newCommunity]);
    setJoinedCommunityIds(prev => [...prev, id]);
    setIsCreatingCommunity(false);
    handleSelectCommunity(id);
  };

  const handleLaunchProject = () => {
    if (!activeCommunityId || !newProjectData.name) return;
    const newProjectId = `p${Date.now()}`;
    const newProject: Project = {
      id: newProjectId,
      name: newProjectData.name,
      description: newProjectData.description,
      communityId: activeCommunityId,
      status: 'Proposed',
      techStack: [],
      contributors: [currentUser.id],
      rolesNeeded: newProjectData.roles.split(',').map(r => r.trim()).filter(r => !!r),
      tasks: [],
      resources: [],
      milestones: newProjectMilestones.filter(m => !!m.trim()).map((m, i) => ({
        id: `m-${i}-${newProjectId}`,
        title: m,
        description: '',
        dueDate: 'TBD',
        status: i === 0 ? 'active' : 'pending'
      })),
      currentVersion: '0.1.0',
      createdBy: currentUser.id
    };
    setProjects(prev => [...prev, newProject]);
    setActiveProjectId(newProjectId);
    setActiveChannelId(null);
    setIsCreatingProject(false);
    setNewProjectData({ name: '', description: '', roles: '' });
    setNewProjectMilestones(['Phase 1: Concept']);
  };

  const handleStartProject = (projectId: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, status: 'Ongoing' } : p));
  };

  const handleAddResource = (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id === projectId) {
        return {
          ...p,
          resources: [...p.resources, { id: Date.now().toString(), title, url, type, size }]
        };
      }
      return p;
    }));
  };

  const addMilestoneInput = () => {
    setNewProjectMilestones(prev => [...prev, `Task ${prev.length + 1}`]);
  };

  const updateMilestoneInput = (idx: number, val: string) => {
    const next = [...newProjectMilestones];
    next[idx] = val;
    setNewProjectMilestones(next);
  };

  const viewedUser = MOCK_USERS.find(u => u.id === selectedUserId) || currentUser;

  if (isLanding) {
    return (
      <div className="min-h-screen bg-white dark:bg-zinc-950 flex flex-col items-center justify-center p-12 overflow-hidden relative">
        <div className="absolute top-0 left-0 w-full h-full opacity-5 pointer-events-none">
          <div className="h-full w-full" style={{backgroundImage: 'radial-gradient(#4f46e5 1px, transparent 1px)', backgroundSize: '40px 40px'}}></div>
        </div>

        <div className="max-w-4xl w-full space-y-16 relative z-10 text-center animate-in fade-in slide-in-from-bottom-8 duration-1000">
           <div className="inline-flex items-center space-x-2 px-4 py-2 bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800 rounded-full text-indigo-600 dark:text-indigo-400 text-xs font-bold tracking-widest uppercase mb-4">
             <span className="flex h-2 w-2 rounded-full bg-indigo-600 mr-2 animate-pulse"></span>
             Built for student builders
           </div>

           <div className="space-y-6">
              <h1 className="text-9xl font-extrabold text-slate-900 dark:text-white tracking-tight leading-none">
                NEXORA
              </h1>
              <p className="text-xl font-medium text-slate-500 dark:text-slate-400 max-w-2xl mx-auto leading-relaxed">
                A unified ecosystem for students to <span className="text-slate-900 dark:text-white font-semibold">architect</span>, <span className="text-slate-900 dark:text-white font-semibold">collaborate</span>, and <span className="text-slate-900 dark:text-white font-semibold">ship</span> world-class software together.
              </p>
           </div>

           <div className="flex flex-col sm:flex-row items-center justify-center gap-6">
              <button 
                onClick={() => { setIsLanding(false); setIsAuthView(true); }}
                className="group px-10 py-5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-lg font-bold text-lg hover:shadow-2xl hover:shadow-indigo-500/20 transition-all flex items-center space-x-3 border border-transparent"
              >
                <img src="https://www.google.com/favicon.ico" className="w-5 h-5 bg-white p-0.5 rounded" alt="G" />
                <span>Continue with Google</span>
              </button>
              <button 
                onClick={() => { setIsLanding(false); setView('explore'); }}
                className="px-10 py-5 bg-white dark:bg-zinc-900 border border-slate-200 dark:border-zinc-800 text-slate-900 dark:text-white rounded-lg font-bold text-lg hover:bg-slate-50 dark:hover:bg-zinc-800 transition-all"
              >
                Browse Projects
              </button>
           </div>

           <div className="pt-16 grid grid-cols-3 gap-8 text-left border-t border-slate-100 dark:border-zinc-900">
              <div>
                <h3 className="font-bold text-slate-900 dark:text-white text-sm mb-2">Technical Networking</h3>
                <p className="text-xs text-slate-500 leading-relaxed">Skip the fluff. Connect based on stacks, repos, and reputation.</p>
              </div>
              <div>
                <h3 className="font-bold text-slate-900 dark:text-white text-sm mb-2">Internal Git Flow</h3>
                <p className="text-xs text-slate-500 leading-relaxed">Project spaces integrated with your workflow. From RFC to Merge.</p>
              </div>
              <div>
                <h3 className="font-bold text-slate-900 dark:text-white text-sm mb-2">Reputation Engine</h3>
                <p className="text-xs text-slate-500 leading-relaxed">Verified contributions that speak louder than any resume.</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  if (isAuthView) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-zinc-950 flex items-center justify-center p-6">
        <div className="bg-white dark:bg-zinc-900 p-10 rounded-xl shadow-2xl w-full max-w-md border border-slate-200 dark:border-zinc-800 animate-in slide-in-from-bottom-8 duration-500">
          <div className="text-center mb-10">
            <h2 className="text-3xl font-bold mb-2 tracking-tight text-slate-900 dark:text-white">Sign In</h2>
            <p className="text-slate-500 text-sm">Welcome back to the builder network.</p>
          </div>
          <div className="space-y-6">
            <button 
              onClick={() => setIsAuthView(false)}
              className="w-full py-4 border border-slate-200 dark:border-zinc-800 rounded-lg font-semibold flex items-center justify-center space-x-3 hover:bg-slate-50 dark:hover:bg-zinc-800 transition-all text-slate-900 dark:text-white"
            >
              <img src="https://www.google.com/favicon.ico" className="w-5 h-5" alt="G" />
              <span>Sign in with Google</span>
            </button>
            <div className="relative flex items-center py-2">
              <div className="flex-1 border-t border-slate-200 dark:border-zinc-800"></div>
              <span className="px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-white dark:bg-zinc-900">Protected Portal</span>
              <div className="flex-1 border-t border-slate-200 dark:border-zinc-800"></div>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Institutional ID</label>
              <input type="email" placeholder="student@university.edu" className="w-full bg-slate-50 dark:bg-zinc-800 border border-slate-200 dark:border-zinc-700 p-3 rounded-lg outline-none focus:ring-1 focus:ring-indigo-500 text-sm font-medium" />
            </div>
            <button 
              onClick={() => setIsAuthView(false)}
              className="w-full py-4 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-600/20 active:scale-[0.98]"
            >
              Enter Dashboard
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-white dark:bg-zinc-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans">
      {/* Creation Modal (Community) */}
      {isCreatingCommunity && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-zinc-950/60 backdrop-blur-sm" onClick={() => setIsCreatingCommunity(false)} />
          <div className="relative bg-white dark:bg-zinc-900 p-8 rounded-xl shadow-2xl w-full max-w-xl animate-in zoom-in duration-200 border border-slate-200 dark:border-zinc-800">
             <h2 className="text-xl font-bold mb-6 tracking-tight">Create Community</h2>
             <div className="space-y-5">
                <input type="text" placeholder="Space Name" className="w-full bg-slate-50 dark:bg-zinc-800 p-3 rounded-lg border border-slate-200 dark:border-zinc-700 outline-none focus:ring-1 focus:ring-indigo-500 font-semibold" value={newCommunityData.name} onChange={e => setNewCommunityData(p => ({ ...p, name: e.target.value }))} />
                <textarea placeholder="Mission statement..." className="w-full bg-slate-50 dark:bg-zinc-800 p-4 rounded-lg border border-slate-200 dark:border-zinc-700 outline-none focus:ring-1 focus:ring-indigo-500 min-h-[120px] text-sm" value={newCommunityData.description} onChange={e => setNewCommunityData(p => ({ ...p, description: e.target.value }))} />
                <div className="flex gap-4 pt-4">
                   <button onClick={() => setIsCreatingCommunity(false)} className="flex-1 py-3 font-bold rounded-lg border border-slate-200 dark:border-zinc-800 hover:bg-slate-50 dark:hover:bg-zinc-800 transition-all text-sm uppercase tracking-wider">Cancel</button>
                   <button onClick={handleCreateCommunity} className="flex-[2] px-10 py-3 bg-indigo-600 text-white rounded-lg font-bold shadow-lg shadow-indigo-600/20 hover:bg-indigo-500 transition-all active:scale-95 text-sm uppercase tracking-wider">Initialize</button>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Project Proposal Modal */}
      {isCreatingProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-zinc-950/60 backdrop-blur-sm" onClick={() => setIsCreatingProject(false)} />
          <div className="relative bg-white dark:bg-zinc-900 p-8 rounded-xl shadow-2xl w-full max-w-xl animate-in zoom-in duration-200 border border-slate-200 dark:border-zinc-800 custom-scrollbar overflow-y-auto max-h-[90vh]">
             <h2 className="text-xl font-bold mb-6 tracking-tight">Project Proposal</h2>
             <div className="space-y-5">
                <div>
                  <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-2 block px-1">Repository Name</label>
                  <input type="text" placeholder="e.g. distributed-ledger" className="w-full bg-slate-50 dark:bg-zinc-800 p-3 rounded-lg border border-slate-200 dark:border-zinc-700 outline-none focus:ring-1 focus:ring-indigo-500 font-semibold" value={newProjectData.name} onChange={e => setNewProjectData(p => ({ ...p, name: e.target.value }))} />
                </div>
                <div>
                  <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-2 block px-1">Milestones</label>
                  <div className="space-y-2">
                    {newProjectMilestones.map((milestone, idx) => (
                      <input key={idx} type="text" placeholder={`Step ${idx + 1}`} className="w-full bg-slate-50 dark:bg-zinc-800 p-2.5 rounded-lg border border-slate-200 dark:border-zinc-700 outline-none focus:ring-1 focus:ring-indigo-500 text-sm" value={milestone} onChange={e => updateMilestoneInput(idx, e.target.value)} />
                    ))}
                    <button onClick={addMilestoneInput} className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest hover:text-indigo-500 px-1">+ Add Stage</button>
                  </div>
                </div>
                <div className="flex gap-4 pt-6">
                   <button onClick={() => setIsCreatingProject(false)} className="flex-1 py-3 font-bold rounded-lg border border-slate-200 dark:border-zinc-800 hover:bg-slate-50 dark:hover:bg-zinc-800 transition-all text-sm uppercase tracking-wider">Cancel</button>
                   <button onClick={handleLaunchProject} className="flex-[2] px-10 py-3 bg-indigo-600 text-white rounded-lg font-bold shadow-lg shadow-indigo-600/20 hover:bg-indigo-500 transition-all active:scale-95 text-sm uppercase tracking-wider">Commit Proposal</button>
                </div>
             </div>
          </div>
        </div>
      )}

      <Sidebar 
        activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} 
        joinedCommunities={joinedCommunities} 
        onSelectCommunity={handleSelectCommunity} 
        onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }} 
        onOpenProfile={() => { handleViewProfile(currentUser.id); }} 
        onOpenHome={() => { setView('home'); setActiveCommunityId(null); }} 
        onCreateCommunity={() => setIsCreatingCommunity(true)} 
      />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-14 flex items-center justify-between px-6 border-b border-slate-100 dark:border-zinc-900 bg-white/50 dark:bg-zinc-950/50 backdrop-blur-xl z-10 flex-shrink-0">
          <div className="flex items-center space-x-2">
            <span className="text-slate-400 font-mono text-xs">~/</span>
            <span className="text-[11px] font-bold uppercase tracking-[0.15em] text-slate-500">{view.replace('-', ' ')}</span>
            {activeCommunity && (
              <>
                <span className="text-slate-300">/</span>
                <span className="text-[11px] font-bold uppercase tracking-[0.15em] text-indigo-600 dark:text-indigo-400">{activeCommunity.name}</span>
              </>
            )}
          </div>
          <div className="flex items-center space-x-4">
            <button onClick={() => setDarkMode(!darkMode)} className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-zinc-800 text-slate-500 transition-all">
              {darkMode ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
              )}
            </button>
          </div>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && (
            <Home 
              onOpenExplore={() => setView('explore')} 
              joinedCount={joinedCommunityIds.length} 
              currentUser={currentUser} 
              onCreateCommunity={() => setIsCreatingCommunity(true)} 
              onViewProfile={handleViewProfile}
            />
          )}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => setPreviewCommunity(community)} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden">
                {activeChannelId ? (
                  <div className="flex-1 p-0 flex flex-col">
                    <ChatWindow 
                      messages={channelMessages[activeChannelId!] || []} 
                      onSendMessage={handleSendMessage} 
                      currentUser={currentUser} 
                      onViewProfile={handleViewProfile}
                      placeholder={`Message # ${activeChannel?.name || 'channel'}...`} 
                    />
                  </div>
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 text-[10px] font-bold uppercase tracking-[0.2em]">Select an active scope</div>
                )}
                <MemberSidebar 
                  community={activeCommunity} 
                  projectMembers={activeProject?.contributors}
                  onViewProfile={handleViewProfile}
                />
              </div>
            </>
          )}
          {(view === 'profile' || view === 'user-profile') && (
            <Profile 
              user={viewedUser} 
              onLogout={handleLogout} 
              isOwnProfile={viewedUser.id === currentUser.id} 
              onClose={() => setView(activeCommunityId ? 'community' : 'home')}
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Project, ChatMessage, Milestone, ProjectResource } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onStartProject?: (id: string) => void;
  onAddResource?: (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onStartProject, onAddResource }) => {
  const isMember = project.contributors.includes(currentUserId);
  const isCreator = project.createdBy === currentUserId;
  const [activeTab, setActiveTab] = useState<'overview' | 'roadmap' | 'discussions' | 'assets'>('overview');
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  const [resTitle, setResTitle] = useState('');
  const [resUrl, setResUrl] = useState('');
  const [resType, setResType] = useState<ProjectResource['type']>('link');
  const [showResForm, setShowResForm] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSendMessage = (content: string) => {
    const user = MOCK_USERS.find(u => u.id === currentUserId);
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUserId,
      senderName: user?.name || 'User',
      senderAvatar: user?.avatar || '',
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleAddRes = (e: React.FormEvent) => {
    e.preventDefault();
    if (!resTitle || !onAddResource) return;

    if (resType === 'file' || resType === 'image') {
      const file = fileInputRef.current?.files?.[0];
      if (file) {
        const localUrl = URL.createObjectURL(file);
        const sizeStr = (file.size / (1024 * 1024)).toFixed(2) + ' MB';
        onAddResource(project.id, resTitle, localUrl, resType, sizeStr);
        setResTitle('');
        setShowResForm(false);
      }
    } else {
      if (resUrl) {
        onAddResource(project.id, resTitle, resUrl, resType);
        setResTitle('');
        setResUrl('');
        setShowResForm(false);
      }
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-zinc-950 overflow-hidden">
      {/* Project Header */}
      <div className="px-8 pt-8 pb-0 border-b border-slate-100 dark:border-zinc-900 bg-slate-50/30 dark:bg-zinc-900/10">
        <div className="flex items-start justify-between mb-8">
          <div className="flex items-center space-x-5">
            <div className="w-12 h-12 bg-white dark:bg-zinc-800 border border-slate-200 dark:border-zinc-700 rounded-lg flex items-center justify-center text-indigo-600 shadow-sm">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
              </svg>
            </div>
            <div>
              <div className="flex items-center space-x-3">
                <h2 className="text-2xl font-bold tracking-tight text-slate-900 dark:text-white uppercase">{project.name}</h2>
                <span className={`text-[9px] font-bold uppercase tracking-widest px-2 py-0.5 rounded border ${
                  project.status === 'Ongoing' ? 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20' : 
                  project.status === 'Proposed' ? 'bg-amber-500/10 text-amber-600 border-amber-500/20' :
                  'bg-slate-100 dark:bg-zinc-800 text-slate-400 border-slate-200 dark:border-zinc-700'
                }`}>
                  {project.status}
                </span>
              </div>
              <p className="text-xs text-slate-500 font-medium mt-1">Version {project.currentVersion || '0.1.0'} • {project.contributors.length} active members</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            {project.status === 'Proposed' && isCreator && (
              <button 
                onClick={() => onStartProject?.(project.id)}
                className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg font-bold text-xs uppercase tracking-wider transition-all shadow-lg shadow-indigo-600/20"
              >
                Launch Instance
              </button>
            )}
            {!isMember && (
              <button className="px-5 py-2.5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-lg font-bold text-xs uppercase tracking-wider transition-all">
                Join Network
              </button>
            )}
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex space-x-8">
          {(['overview', 'roadmap', 'discussions', 'assets'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`pb-3 text-[10px] font-bold uppercase tracking-[0.2em] transition-all border-b-2 ${
                activeTab === tab 
                  ? 'border-indigo-600 text-indigo-600' 
                  : 'border-transparent text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar">
        {activeTab === 'overview' && (
          <div className="p-10 max-w-4xl space-y-12 animate-in fade-in duration-300">
            <section className="space-y-4">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 dark:border-zinc-900 pb-2">Technical Description</h3>
              <p className="text-slate-600 dark:text-slate-400 leading-relaxed font-medium">
                {project.description}
              </p>
            </section>

            <section className="space-y-4">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 dark:border-zinc-900 pb-2">Active Roles</h3>
              <div className="flex flex-wrap gap-2">
                {project.rolesNeeded?.map(role => (
                  <span key={role} className="bg-slate-50 dark:bg-zinc-900 border border-slate-200 dark:border-zinc-800 px-4 py-2 rounded-lg text-[10px] font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider">
                    {role}
                  </span>
                ))}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'roadmap' && (
          <div className="p-10 max-w-3xl animate-in slide-in-from-bottom-4 duration-300">
             <div className="relative space-y-10 pl-6 border-l-2 border-slate-100 dark:border-zinc-900 ml-4">
                {project.milestones && project.milestones.map((m, idx) => (
                  <div key={m.id} className="relative">
                    <div className={`absolute -left-[35px] top-0 w-4 h-4 rounded-full border-4 border-white dark:border-zinc-950 ${
                      m.status === 'completed' ? 'bg-emerald-500' :
                      m.status === 'active' ? 'bg-indigo-600' : 'bg-slate-200 dark:bg-zinc-800'
                    }`} />
                    <div className="bg-white dark:bg-zinc-900 border border-slate-200 dark:border-zinc-800 p-5 rounded-lg shadow-sm">
                       <span className={`text-[9px] font-bold uppercase tracking-[0.2em] mb-1 block ${m.status === 'active' ? 'text-indigo-600' : 'text-slate-400'}`}>
                         Phase {idx + 1} • {m.status}
                       </span>
                       <h4 className="font-bold text-slate-900 dark:text-white uppercase text-sm tracking-tight">{m.title}</h4>
                    </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {activeTab === 'discussions' && (
          <div className="h-full flex flex-col p-0 bg-slate-50 dark:bg-zinc-950 animate-in fade-in duration-300">
            {isMember ? (
              <ChatWindow 
                messages={messages} 
                onSendMessage={handleSendMessage} 
                currentUser={MOCK_USERS.find(u => u.id === currentUserId)!}
                placeholder="Team internal discussion channel..."
              />
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-center py-20 opacity-40 grayscale">
                <svg className="h-12 w-12 mb-4 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                <p className="text-[10px] font-bold uppercase tracking-widest">Confidential scope • Join required</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'assets' && (
          <div className="p-10 space-y-10 animate-in fade-in duration-300">
             <div className="flex items-center justify-between">
                <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Project Assets</h3>
                {isMember && (
                  <button onClick={() => setShowResForm(!showResForm)} className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest bg-indigo-50 dark:bg-indigo-900/20 px-4 py-2 rounded-lg border border-indigo-100 dark:border-indigo-800 hover:bg-indigo-600 hover:text-white transition-all">
                    {showResForm ? 'Discard Form' : 'Append Asset'}
                  </button>
