import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, User } from '../types';

interface ChatWindowProps {
  messages: ChatMessage[];
  onSendMessage: (content: string) => void;
  currentUser: User;
  onViewProfile?: (userId: string) => void;
  placeholder?: string;
}

const ChatWindow: React.FC<ChatWindowProps> = ({ messages, onSendMessage, currentUser, onViewProfile, placeholder = "Input..." }) => {
  const [inputValue, setInputValue] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!inputValue.trim()) return;
    onSendMessage(inputValue);
    setInputValue('');
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSend();
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-zinc-950">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center opacity-20 grayscale">
            <p className="text-[11px] font-bold uppercase tracking-[0.2em]">Buffer empty</p>
          </div>
        ) : (
          messages.map((msg) => (
            <div key={msg.id} className="group flex items-start space-x-5 animate-in fade-in slide-in-from-bottom-2">
              <button onClick={() => onViewProfile?.(msg.senderId)} className="flex-shrink-0">
                <img src={msg.senderAvatar} className="w-9 h-9 rounded bg-slate-100 dark:bg-zinc-800 border border-slate-200 dark:border-zinc-700" alt="" />
              </button>
              <div className="flex-1 min-w-0">
                <div className="flex items-baseline space-x-3 mb-1">
                  <button onClick={() => onViewProfile?.(msg.senderId)} className="text-xs font-bold text-slate-900 dark:text-white uppercase tracking-tight hover:text-indigo-600 transition-colors">
                    {msg.senderName}
                  </button>
                  <span className="text-[9px] font-mono text-slate-400 uppercase">{msg.timestamp}</span>
                </div>
                <div className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed font-medium">
                  {msg.content}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
      <div className="p-6 border-t border-slate-100 dark:border-zinc-900 bg-white dark:bg-zinc-950">
        <div className="relative flex items-center">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder={placeholder} 
            className="w-full bg-slate-50 dark:bg-zinc-900/50 border border-slate-200 dark:border-zinc-800 px-6 py-4 rounded-lg outline-none focus:ring-1 focus:ring-indigo-500 transition-all text-sm font-medium pr-16"
          />
          <button 
            onClick={handleSend}
            className="absolute right-3 p-2 bg-indigo-600 text-white rounded hover:bg-indigo-500 transition-all shadow-lg shadow-indigo-600/20 active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatWindow;

