import React from 'react';
import { Community, User, Role } from '../types';
import { MOCK_USERS } from '../constants';

interface MemberSidebarProps {
  community: Community;
  projectMembers?: string[];
  onViewProfile?: (userId: string) => void;
}

const MemberSidebar: React.FC<MemberSidebarProps> = ({ community, projectMembers, onViewProfile }) => {
  const getMembersInRole = (roleId: string) => {
    let members = community.members.filter(m => m.roleId === roleId);
    if (projectMembers) {
      members = members.filter(m => projectMembers.includes(m.userId));
    }
    return members;
  };

  const currentCount = projectMembers ? projectMembers.length : community.memberCount;

  return (
    <div className="w-64 bg-slate-50/50 dark:bg-zinc-950 border-l border-slate-100 dark:border-zinc-900 flex flex-col flex-shrink-0 h-full">
      <div className="p-6 border-b border-slate-100 dark:border-zinc-900">
        <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">
          {projectMembers ? 'Scope Access' : 'Network Base'}
        </h3>
        <p className="text-xs font-mono text-slate-400 mt-1 uppercase tracking-tighter">Verified: {currentCount}</p>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-10 custom-scrollbar">
        {community.roles.map(role => {
          const members = getMembersInRole(role.id);
          if (members.length === 0) return null;
          return (
            <div key={role.id}>
              <h4 className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-4 px-2 opacity-60">
                {role.name} • {members.length}
              </h4>
              <div className="space-y-1">
                {members.map(member => {
                  const user = MOCK_USERS.find(u => u.id === member.userId);
                  if (!user) return null;
                  return (
                    <button 
                      key={user.id} 
                      onClick={() => onViewProfile?.(user.id)}
                      className="w-full flex items-center space-x-3 p-2 rounded-lg hover:bg-white dark:hover:bg-zinc-900 transition-all group text-left border border-transparent hover:border-slate-100 dark:hover:border-zinc-800 shadow-sm hover:shadow-md"
                    >
                      <div className="relative">
                        <img src={user.avatar} className="w-8 h-8 rounded border border-slate-200 dark:border-zinc-800" alt="" />
                        <div className="absolute -bottom-0.5 -right-0.5 w-2 h-2 bg-emerald-500 border border-white dark:border-zinc-950 rounded-full" />
                      </div>
                      <span className={`text-xs font-bold truncate group-hover:text-indigo-600 transition-colors uppercase tracking-tight ${role.color}`}>
                        {user.name}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default MemberSidebar;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Milestone, ProjectResource } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview' | 'user-profile'>('home');
  const [darkMode, setDarkMode] = useState(true);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);

  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Infrastructure sync complete. The Nexora internal architecture is ready for scale.', timestamp: '10:05 AM' },
    ]
  });

  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', tagline: '', description: '' });
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });
  const [newProjectMilestones, setNewProjectMilestones] = useState<string[]>(['Initialization']);

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.add('light');
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
    setView('community');
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
    setView('community');
  };

  const handleViewProfile = (userId: string) => {
    setSelectedUserId(userId);
    setView('user-profile');
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  const handleCreateCommunity = () => {
    if (!newCommunityData.name) return;
    const id = `c${Date.now()}`;
    const newCommunity: Community = {
      id,
      name: newCommunityData.name,
      description: newCommunityData.description,
      icon: '🏛️',
      memberCount: 1,
      projectCount: 0,
      tags: ['new-community'],
      createdBy: currentUser.id,
      roles: [
        { id: 'r1', name: 'Maintainer', color: 'text-indigo-400' },
        { id: 'r2', name: 'Member', color: 'text-slate-400' }
      ],
      members: [{ userId: currentUser.id, roleId: 'r1' }],
      channels: [{ id: `ch_g_${id}`, name: 'general', type: 'chat' }]
    };
    setCommunities(prev => [...prev, newCommunity]);
    setJoinedCommunityIds(prev => [...prev, id]);
    setIsCreatingCommunity(false);
    handleSelectCommunity(id);
  };

  const handleLaunchProject = () => {
    if (!activeCommunityId || !newProjectData.name) return;
    const newProjectId = `p${Date.now()}`;
    const newProject: Project = {
      id: newProjectId,
      name: newProjectData.name,
      description: newProjectData.description,
      communityId: activeCommunityId,
      status: 'Proposed',
      techStack: [],
      contributors: [currentUser.id],
      rolesNeeded: newProjectData.roles.split(',').map(r => r.trim()).filter(r => !!r),
      tasks: [],
      resources: [],
      milestones: newProjectMilestones.filter(m => !!m.trim()).map((m, i) => ({
        id: `m-${i}-${newProjectId}`,
        title: m,
        description: '',
        dueDate: 'TBD',
        status: i === 0 ? 'active' : 'pending'
      })),
      currentVersion: '0.1.0',
      createdBy: currentUser.id
    };
    setProjects(prev => [...prev, newProject]);
    setActiveProjectId(newProjectId);
    setActiveChannelId(null);
    setIsCreatingProject(false);
    setNewProjectData({ name: '', description: '', roles: '' });
    setNewProjectMilestones(['Project Init']);
  };

  const handleStartProject = (projectId: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, status: 'Ongoing' } : p));
  };

  const handleAddResource = (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id === projectId) {
        return {
          ...p,
          resources: [...p.resources, { id: Date.now().toString(), title, url, type, size }]
        };
      }
      return p;
    }));
  };

  const viewedUser = MOCK_USERS.find(u => u.id === selectedUserId) || currentUser;

  if (isLanding) {
    return (
      <div className="min-h-screen bg-zinc-950 flex flex-col items-center justify-center p-6 md:p-12 overflow-hidden relative">
        <div className="absolute inset-0 hero-grid opacity-20 pointer-events-none"></div>
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-pink-600/5 blur-[120px] rounded-full"></div>

        <div className="max-w-5xl w-full relative z-10 text-center animate-in fade-in slide-in-from-bottom-12 duration-1000">
           <div className="inline-flex items-center space-x-2 px-3 py-1.5 glass-card rounded-full text-indigo-400 text-[10px] font-bold tracking-[0.2em] uppercase mb-8">
             <span className="flex h-1.5 w-1.5 rounded-full bg-indigo-500 mr-2 animate-pulse"></span>
             Engineered for High-Performance Students
           </div>

           <h1 className="text-7xl md:text-9xl font-extrabold text-white tracking-tighter leading-tight mb-8">
             NEXORA<span className="text-indigo-500">.</span>
           </h1>

           <p className="text-lg md:text-xl font-medium text-slate-400 max-w-2xl mx-auto leading-relaxed mb-12">
             The single source of truth for student architects. <span className="text-white">Coordinate</span> technical projects, <span className="text-white">Manage</span> repos, and <span className="text-white">Accelerate</span> your builder journey.
           </p>

           <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
              <button 
                onClick={() => { setIsLanding(false); setIsAuthView(true); }}
