             </button>
          </div>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && (
            <Home 
              onOpenExplore={() => setView('explore')} 
              joinedCount={joinedCommunityIds.length} 
              currentUser={currentUser} 
              onCreateCommunity={() => setIsCreatingCommunity(true)} 
              onViewProfile={handleViewProfile}
            />
          )}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => setPreviewCommunity(community)} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden bg-zinc-900/50">
                {activeChannelId ? (
                  <ChatWindow 
                    messages={channelMessages[activeChannelId!] || []} 
                    onSendMessage={handleSendMessage} 
                    currentUser={currentUser} 
                    onViewProfile={handleViewProfile}
                    placeholder={`Sync message with #${activeChannel?.name || 'channel'}...`} 
                  />
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 text-[10px] font-bold uppercase tracking-[0.25em]">Waiting for scope selection...</div>
                )}
                <MemberSidebar 
                  community={activeCommunity} 
                  projectMembers={activeProject?.contributors}
                  onViewProfile={handleViewProfile}
                />
              </div>
            </>
          )}
          {(view === 'profile' || view === 'user-profile') && (
            <Profile 
              user={viewedUser} 
              onLogout={handleLogout} 
              isOwnProfile={viewedUser.id === currentUser.id} 
              onClose={() => setView(activeCommunityId ? 'community' : 'home')}
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MOCK_DMS, MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';
import { ChatMessage, User } from '../types';

interface HomeProps {
  onOpenExplore: () => void;
  joinedCount: number;
  currentUser: User;
  onCreateCommunity: () => void;
  onViewProfile?: (userId: string) => void;
}

const Home: React.FC<HomeProps> = ({ onOpenExplore, joinedCount, currentUser, onCreateCommunity, onViewProfile }) => {
  const [activeDmId, setActiveDmId] = useState<string | null>(null);
  const [dmHistory, setDmHistory] = useState<Record<string, ChatMessage[]>>({
    'dm1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Sync required on the new design specs for Nexora v0.4.0.', timestamp: '2:15 PM' }
    ]
  });

  const activeDm = MOCK_DMS.find(dm => dm.id === activeDmId);

  const handleSendMessage = (content: string) => {
    if (!activeDmId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setDmHistory(prev => ({
      ...prev,
      [activeDmId]: [...(prev[activeDmId] || []), newMessage]
    }));
  };

  return (
    <div className="flex-1 flex overflow-hidden bg-zinc-950">
      <div className="flex-1 overflow-y-auto p-12 flex flex-col items-center justify-center relative custom-scrollbar">
        <div className="absolute top-[-20%] left-[-20%] w-[50%] h-[50%] bg-indigo-600/5 blur-[160px] rounded-full"></div>

        {!activeDmId ? (
          <div className="animate-in fade-in slide-in-from-bottom-6 duration-700 text-center max-w-2xl w-full">
            <div className="w-20 h-20 rounded-2xl bg-zinc-900 border border-white/10 flex items-center justify-center mx-auto mb-10 shadow-2xl text-indigo-500">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 16l2.879-2.879m0 0a3 3 0 104.243-4.242 3 3 0 00-4.243 4.242zM21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
               </svg>
            </div>
            <h2 className="text-5xl font-extrabold text-white mb-6 tracking-tighter">Terminal Ready<span className="text-indigo-500">_</span></h2>
            <p className="text-slate-400 mb-12 text-lg font-medium leading-relaxed">
              Active in <span className="text-white">{joinedCount} dedicated communities</span>. Your contribution roadmap is up to date. Ready to deploy the next idea?
            </p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <button onClick={onOpenExplore} className="px-10 py-4 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-600/20 active:scale-95 uppercase tracking-widest">
                Explore Nodes
              </button>
              <button onClick={onCreateCommunity} className="px-10 py-4 bg-zinc-900 border border-white/10 text-white rounded-lg font-bold text-sm hover:bg-zinc-800 transition-all active:scale-95 uppercase tracking-widest">
                Spawn Space
              </button>
            </div>
          </div>
        ) : (
          <div className="w-full h-full flex flex-col animate-in fade-in duration-300">
             <div className="flex items-center justify-between mb-8 px-4">
               <div className="flex items-center space-x-6">
                  <button onClick={() => setActiveDmId(null)} className="p-2 hover:bg-white/5 rounded-lg text-slate-500 hover:text-white">
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                  </button>
                  <button onClick={() => activeDm && onViewProfile?.(activeDm.userId)} className="flex items-center space-x-4 hover:opacity-80 transition-opacity">
                    <img src={activeDm?.senderAvatar} className="w-10 h-10 rounded-lg border border-white/10" alt="" />
                    <div className="text-left">
                      <h3 className="font-bold text-lg text-white leading-none">{activeDm?.senderName}</h3>
                      <span className="text-[10px] text-emerald-500 font-bold uppercase tracking-widest mt-1 block">Online</span>
                    </div>
                  </button>
               </div>
             </div>
             <ChatWindow 
              messages={dmHistory[activeDmId] || []} 
              onSendMessage={handleSendMessage} 
              currentUser={currentUser}
              onViewProfile={onViewProfile}
              placeholder={`Comm message to ${activeDm?.senderName.split(' ')[0]}...`}
             />
          </div>
        )}
      </div>

      {/* DMs Sidebar - Refined */}
      <div className="w-80 bg-zinc-950 border-l border-white/5 flex flex-col flex-shrink-0">
        <div className="p-8 border-b border-white/5 flex items-center justify-between">
          <h3 className="font-bold text-slate-500 uppercase tracking-[0.2em] text-[10px]">Active Transmissions</h3>
          <button className="text-slate-500 hover:text-indigo-400 transition-colors">
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-1">
          {MOCK_DMS.map((dm) => (
