            >
              <div className="relative flex-shrink-0">
                <img src={dm.senderAvatar} className="w-11 h-11 rounded-lg border border-white/10" alt="" />
                <div className={`absolute -top-1 -right-1 w-3 h-3 border-2 border-zinc-950 rounded-full ${dm.unread ? 'bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.8)]' : 'bg-zinc-600'}`} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-baseline mb-1">
                  <span className={`text-sm font-bold truncate ${dm.unread ? 'text-white' : 'text-slate-400'}`}>
                    {dm.senderName}
                  </span>
                  <span className="text-[9px] font-mono text-slate-600 flex-shrink-0 ml-2">{dm.timestamp}</span>
                </div>
                <p className={`text-xs truncate font-medium ${dm.unread ? 'text-slate-300' : 'text-slate-500'}`}>
                  {dm.lastMessage}
                </p>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

