import React, { useState, useRef } from 'react';
import { Project, ChatMessage, Milestone, ProjectResource } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onStartProject?: (id: string) => void;
  onAddResource?: (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onStartProject, onAddResource }) => {
  const isMember = project.contributors.includes(currentUserId);
  const isCreator = project.createdBy === currentUserId;
  const [activeTab, setActiveTab] = useState<'overview' | 'roadmap' | 'scope' | 'artifacts'>('overview');
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  const [resTitle, setResTitle] = useState('');
  const [resUrl, setResUrl] = useState('');
  const [resType, setResType] = useState<ProjectResource['type']>('link');
  const [showResForm, setShowResForm] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSendMessage = (content: string) => {
    const user = MOCK_USERS.find(u => u.id === currentUserId);
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUserId,
      senderName: user?.name || 'User',
      senderAvatar: user?.avatar || '',
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleAddRes = (e: React.FormEvent) => {
    e.preventDefault();
    if (!resTitle || !onAddResource) return;

    if (resType === 'file' || resType === 'image') {
      const file = fileInputRef.current?.files?.[0];
      if (file) {
        const localUrl = URL.createObjectURL(file);
        const sizeStr = (file.size / (1024 * 1024)).toFixed(2) + ' MB';
        onAddResource(project.id, resTitle, localUrl, resType, sizeStr);
        setResTitle('');
        setShowResForm(false);
      }
    } else {
      if (resUrl) {
        onAddResource(project.id, resTitle, resUrl, resType);
        setResTitle('');
        setResUrl('');
        setShowResForm(false);
      }
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-zinc-950 overflow-hidden animate-in fade-in duration-500">
      {/* Project Banner Header */}
      <div className="px-10 pt-10 pb-0 border-b border-white/5 bg-zinc-900/10">
        <div className="flex items-start justify-between mb-10">
          <div className="flex items-center space-x-6">
            <div className="w-16 h-16 bg-zinc-900 border border-white/10 rounded-2xl flex items-center justify-center text-brand-500 shadow-2xl ring-1 ring-brand-500/20">
              <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2-1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1V18.5M7 18l-2-1m2 1l2-1m-2 1V15.5M21 12l-2-1m2 1l2-1m-2 1V9.5M12 12l2 1m-2-1l-2 1m2-1V9.5" />
              </svg>
            </div>
            <div>
              <div className="flex items-center space-x-4 mb-1">
                <h2 className="text-3xl font-black tracking-tighter text-white uppercase">{project.name}</h2>
                <div className={`px-2.5 py-0.5 rounded text-[8px] font-black uppercase tracking-[0.2em] border ${
                  project.status === 'Ongoing' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 
                  project.status === 'Proposed' ? 'bg-brand-500/10 text-brand-400 border-brand-500/20' :
                  'bg-zinc-800 text-slate-500 border-white/5'
                }`}>
                  {project.status}
                </div>
              </div>
              <p className="text-xs text-slate-500 font-mono tracking-tighter">v{project.currentVersion || '0.1.0'} &bull; Contributors_{project.contributors.length} &bull; Community_Access_Node</p>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            {project.status === 'Proposed' && isCreator && (
              <button 
                onClick={() => onStartProject?.(project.id)}
                className="px-6 py-3 bg-brand-600 hover:bg-brand-500 text-white rounded-xl font-bold text-xs uppercase tracking-widest transition-all shadow-xl shadow-brand-500/20 active:scale-95"
              >
                Launch Scope
              </button>
            )}
            {!isMember && (
              <button className="px-6 py-3 bg-white text-zinc-950 rounded-xl font-bold text-xs uppercase tracking-widest transition-all shadow-xl shadow-white/10">
                Join Network
              </button>
            )}
          </div>
        </div>

        {/* Engineering Tabs */}
        <div className="flex space-x-10">
          {(['overview', 'roadmap', 'scope', 'artifacts'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`pb-4 text-[10px] font-bold uppercase tracking-[0.3em] transition-all border-b-2 relative ${
                activeTab === tab 
                  ? 'border-brand-500 text-white' 
                  : 'border-transparent text-slate-500 hover:text-slate-300'
              }`}
            >
              {tab}
              {activeTab === tab && <div className="absolute -bottom-[2px] left-0 w-full h-[2px] bg-brand-500 shadow-[0_0_10px_#8b5cf6]"></div>}
            </button>
          ))}
        </div>
      </div>

