import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, User } from '../types';

interface ChatWindowProps {
  messages: ChatMessage[];
  onSendMessage: (content: string) => void;
  currentUser: User;
  onViewProfile?: (userId: string) => void;
  placeholder?: string;
}

const ChatWindow: React.FC<ChatWindowProps> = ({ messages, onSendMessage, currentUser, onViewProfile, placeholder = "Comm message..." }) => {
  const [inputValue, setInputValue] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!inputValue.trim()) return;
    onSendMessage(inputValue);
    setInputValue('');
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSend();
  };

  return (
    <div className="flex flex-col h-full bg-transparent">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center opacity-10 select-none">
            <p className="text-[11px] font-bold uppercase tracking-[0.5em] text-white">Buffer_Empty_Wait_For_Input</p>
          </div>
        ) : (
          messages.map((msg) => (
            <div key={msg.id} className="group flex items-start space-x-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
              <button onClick={() => onViewProfile?.(msg.senderId)} className="flex-shrink-0 relative">
                <img src={msg.senderAvatar} className="w-10 h-10 rounded-xl bg-zinc-900 border border-white/10 group-hover:border-brand-500/50 transition-all duration-300" alt="" />
                <div className="absolute inset-0 rounded-xl bg-brand-500/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
              </button>
              <div className="flex-1 min-w-0">
                <div className="flex items-baseline space-x-4 mb-2">
                  <button onClick={() => onViewProfile?.(msg.senderId)} className="text-xs font-bold text-white uppercase tracking-wider hover:text-brand-400 transition-colors">
                    {msg.senderName}
                  </button>
                  <span className="text-[9px] font-mono text-slate-600 uppercase tracking-tighter">{msg.timestamp}</span>
                </div>
                <div className="text-[13px] text-slate-400 leading-relaxed font-medium">
                  {msg.content}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
      <div className="p-8 border-t border-white/5 bg-zinc-950/80 backdrop-blur-xl">
        <div className="relative flex items-center group">
          <div className="absolute left-6 text-brand-500/50 font-mono text-xs group-focus-within:text-brand-500 transition-colors">&gt;</div>
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder={placeholder} 
            className="w-full bg-zinc-900/50 border border-white/10 pl-12 pr-16 py-5 rounded-2xl outline-none focus:ring-1 focus:ring-brand-500/50 transition-all text-sm font-medium text-white placeholder:text-slate-600"
          />
          <button 
            onClick={handleSend}
            className="absolute right-4 p-3 bg-white text-zinc-950 rounded-xl hover:bg-brand-500 hover:text-white transition-all shadow-xl active:scale-95"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatWindow;

import React from 'react';
import { Community, User, Role } from '../types';
import { MOCK_USERS } from '../constants';

interface MemberSidebarProps {
  community: Community;
  projectMembers?: string[];
  onViewProfile?: (userId: string) => void;
}

const MemberSidebar: React.FC<MemberSidebarProps> = ({ community, projectMembers, onViewProfile }) => {
  const getMembersInRole = (roleId: string) => {
    let members = community.members.filter(m => m.roleId === roleId);
    if (projectMembers) {
      members = members.filter(m => projectMembers.includes(m.userId));
    }
    return members;
  };

  const currentCount = projectMembers ? projectMembers.length : community.memberCount;

  return (
    <div className="w-64 bg-zinc-950 border-l border-white/5 flex flex-col flex-shrink-0 h-full relative z-10 shadow-[-20px_0_40px_rgba(0,0,0,0.3)]">
      <div className="p-10 border-b border-white/5 bg-zinc-900/10">
        <h3 className="text-[10px] font-bold text-slate-600 uppercase tracking-[0.4em] mb-2">
          {projectMembers ? 'Scope_Access' : 'Registry'}
        </h3>
        <p className="text-[9px] font-mono text-brand-500/70 uppercase tracking-widest font-bold">Verified_Nodes: {currentCount}</p>
      </div>
      <div className="flex-1 overflow-y-auto p-6 space-y-12 custom-scrollbar">
        {community.roles.map(role => {
          const members = getMembersInRole(role.id);
          if (members.length === 0) return null;
          return (
            <div key={role.id}>
              <h4 className="text-[9px] font-bold uppercase tracking-[0.2em] text-slate-600 mb-6 px-2 flex items-center">
                <span className="w-3 h-px bg-white/5 mr-2"></span>
                {role.name} &bull; {members.length}
              </h4>
              <div className="space-y-1.5">
                {members.map(member => {
                  const user = MOCK_USERS.find(u => u.id === member.userId);
                  if (!user) return null;
                  return (
                    <button 
                      key={user.id} 
                      onClick={() => onViewProfile?.(user.id)}
                      className="w-full flex items-center space-x-4 p-2.5 rounded-xl hover:bg-white/[0.03] transition-all group text-left border border-transparent hover:border-white/5"
                    >
                      <div className="relative">
                        <img src={user.avatar} className="w-9 h-9 rounded-lg border border-white/10 grayscale group-hover:grayscale-0 transition-all duration-300" alt="" />
                        <div className="absolute -bottom-1 -right-1 w-2.5 h-2.5 bg-emerald-500 border-[3px] border-zinc-950 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)]" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <span className={`text-[11px] font-bold truncate group-hover:text-white transition-colors uppercase tracking-tight block ${role.color}`}>
                          {user.name}
                        </span>
                        <span className="text-[8px] font-mono text-slate-700 uppercase tracking-tighter block mt-0.5">Contributor_Tier_01</span>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

