import { Community, Project, ChatMessage, User, Milestone, ProjectResource } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview' | 'user-profile'>('home');
  const [darkMode, setDarkMode] = useState(true);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);

  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Operational ready. All internal nodes are synced for Nexora v0.4.5.', timestamp: '10:05 AM' },
    ]
  });

  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', tagline: '', description: '' });
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [darkMode]);

  // Derived state to fix missing references
  const activeCommunity = communities.find(c => c.id === activeCommunityId);
  const activeProject = projects.find(p => p.id === activeProjectId);
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);
  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const viewedUser = MOCK_USERS.find(u => u.id === selectedUserId) || currentUser;

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
    setView('community');
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
    setView('community');
  };

  const handleViewProfile = (userId: string) => {
    setSelectedUserId(userId);
    setView('user-profile');
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  // Missing handlers implementation
  const handleStartProject = (projectId: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, status: 'Ongoing' as const } : p));
  };

  const handleAddResource = (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => {
    const newRes: ProjectResource = {
      id: Date.now().toString(),
      title,
      url,
      type,
      size
    };
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, resources: [...p.resources, newRes] } : p));
  };

  if (isLanding) {
    return (
      <div className="min-h-screen bg-zinc-950 flex flex-col items-center justify-center p-8 overflow-hidden relative">
        <div className="absolute inset-0 hero-gradient pointer-events-none opacity-40"></div>
        <div className="absolute top-0 left-0 w-full h-full hero-grid opacity-10 pointer-events-none"></div>

        <div className="max-w-4xl w-full relative z-10 text-center space-y-12 animate-in fade-in slide-in-from-bottom-12 duration-1000">
           <div className="inline-flex items-center space-x-2 px-4 py-2 glass-card rounded-full text-brand-400 text-[10px] font-bold tracking-[0.25em] uppercase border border-brand-500/20 mb-4 animate-float">
             <span className="flex h-2 w-2 rounded-full bg-brand-500 shadow-[0_0_10px_#8b5cf6] mr-2"></span>
             Built for Student Architects
           </div>

           <div className="space-y-6">
              <h1 className="text-8xl md:text-[10rem] font-black tracking-tighter text-white leading-none">
                NEXORA<span className="text-brand-500">_</span>
              </h1>
              <p className="text-lg md:text-xl font-medium text-slate-400 max-w-2xl mx-auto leading-relaxed">
                Coordinate. Develop. Deploy. The technical network where <span className="text-white">student builders</span> scale together.
              </p>
           </div>

           <div className="flex flex-col sm:flex-row items-center justify-center gap-6 pt-8">
              <button 
                onClick={() => { setIsLanding(false); setIsAuthView(true); }}
                className="group relative px-10 py-4 bg-white text-zinc-950 rounded-xl font-bold text-sm hover:scale-105 active:scale-95 transition-all flex items-center space-x-3 shadow-[0_0_20px_rgba(255,255,255,0.1)]"
              >
                <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="G" />
                <span>Get Started with Google</span>
              </button>
              <button 
                onClick={() => { setIsLanding(false); setView('explore'); }}
                className="px-10 py-4 glass-card text-white rounded-xl font-bold text-sm hover:bg-white/5 transition-all border border-white/5 uppercase tracking-widest"
              >
                Explore Nodes
              </button>
           </div>

           <div className="pt-24 grid grid-cols-1 md:grid-cols-3 gap-8 text-left max-w-5xl mx-auto">
              <div className="p-8 glass-card rounded-2xl group cursor-default">
                <div className="w-10 h-10 bg-brand-500/10 rounded-lg flex items-center justify-center text-brand-400 mb-6 group-hover:scale-110 transition-transform border border-brand-500/20">
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" /></svg>
                </div>
                <h3 className="font-bold text-white text-sm uppercase tracking-wider mb-2">Dev Context</h3>
                <p className="text-[11px] text-slate-500 leading-relaxed font-medium">Native roadmap integration. Connect via actual commits, not noise.</p>
              </div>
              <div className="p-8 glass-card rounded-2xl group cursor-default">
                <div className="w-10 h-10 bg-brand-500/10 rounded-lg flex items-center justify-center text-brand-400 mb-6 group-hover:scale-110 transition-transform border border-brand-500/20">
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                </div>
                <h3 className="font-bold text-white text-sm uppercase tracking-wider mb-2">High Velocity</h3>
                <p className="text-[11px] text-slate-500 leading-relaxed font-medium">Initialize projects instantly. Recruit based on stack verified reputation.</p>
              </div>
              <div className="p-8 glass-card rounded-2xl group cursor-default">
                <div className="w-10 h-10 bg-brand-500/10 rounded-lg flex items-center justify-center text-brand-400 mb-6 group-hover:scale-110 transition-transform border border-brand-500/20">
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 11c0 3.517-1.009 6.799-2.753 9.571m-3.44-2.04l.054-.09A10.003 10.003 0 0012 20c4.083 0 7.674-2.43 9.32-5.928M9 11V9c0-1.105.895-2 2-2h2c1.105 0 2 .895 2 2v2m-6 0h6" /></svg>
                </div>
                <h3 className="font-bold text-white text-sm uppercase tracking-wider mb-2">Proof of Skill</h3>
                <p className="text-[11px] text-slate-500 leading-relaxed font-medium">Reputation index built on real execution history and community validation.</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  if (isAuthView) {
    return (
      <div className="min-h-screen bg-zinc-950 flex items-center justify-center p-6 relative">
        <div className="absolute inset-0 hero-grid opacity-5"></div>
        <div className="relative glass-card p-12 rounded-2xl shadow-2xl w-full max-w-md border border-white/5 animate-in zoom-in duration-500">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold mb-3 tracking-tighter text-white uppercase">Initialize Account</h2>
            <p className="text-slate-500 text-xs font-medium uppercase tracking-[0.2em]">Authorized Personnel Only</p>
          </div>
          <div className="space-y-6">
            <button 
              onClick={() => setIsAuthView(false)}
              className="w-full py-4 bg-white text-zinc-950 rounded-xl font-bold flex items-center justify-center space-x-3 hover:scale-[1.02] active:scale-95 transition-all text-sm"
            >
              <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="G" />
              <span>Continue with Google</span>
            </button>
            <div className="relative flex items-center py-4">
              <div className="flex-1 border-t border-white/5"></div>
              <span className="px-4 text-[9px] font-bold text-slate-600 uppercase tracking-widest">or secure ID</span>
              <div className="flex-1 border-t border-white/5"></div>
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">University Email</label>
              <input type="email" placeholder="builder@insti.edu" className="w-full bg-zinc-900 border border-white/10 p-4 rounded-xl outline-none focus:ring-1 focus:ring-brand-500 text-sm font-mono" />
            </div>
            <button 
              onClick={() => setIsAuthView(false)}
              className="w-full py-4 bg-brand-600 text-white rounded-xl font-bold text-xs uppercase tracking-[0.2em] hover:bg-brand-500 transition-all shadow-xl shadow-brand-500/20 mt-4"
            >
              Access Terminal
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-zinc-950 overflow-hidden text-slate-200 font-sans selection:bg-brand-500/30">
      <Sidebar 
        activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} 
        joinedCommunities={communities.filter(c => joinedCommunityIds.includes(c.id))} 
        onSelectCommunity={handleSelectCommunity} 
        onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }} 
        onOpenProfile={() => { handleViewProfile(currentUser.id); }} 
        onOpenHome={() => { setView('home'); setActiveCommunityId(null); }} 
        onCreateCommunity={() => setIsCreatingCommunity(true)} 
      />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-14 flex items-center justify-between px-8 border-b border-white/5 bg-zinc-950/50 backdrop-blur-2xl z-20">
          <div className="flex items-center space-x-4">
            <span className="text-brand-500 font-mono text-xs opacity-60">root@nexora:~</span>
            <span className="text-[10px] font-bold uppercase tracking-[0.3em] text-slate-500">{view.replace('-', ' ')}</span>
            {activeCommunity && (
              <>
                <span className="text-zinc-800 font-light">/</span>
                <span className="text-[10px] font-bold uppercase tracking-[0.3em] text-white underline decoration-brand-500 underline-offset-4">{activeCommunity.name}</span>
              </>
            )}
          </div>
          <div className="flex items-center space-x-6">
             <div className="flex items-center space-x-3 px-3 py-1 bg-emerald-500/5 border border-emerald-500/10 rounded-full">
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                <span className="text-[9px] font-bold text-emerald-500 tracking-widest">LIVE_SYNC</span>
             </div>
             <button onClick={() => setDarkMode(!darkMode)} className="p-2 text-slate-500 hover:text-white transition-colors">
                {darkMode ? <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg> : <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>}
             </button>
          </div>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && (
            <Home 
              onOpenExplore={() => setView('explore')} 
              joinedCount={joinedCommunityIds.length} 
              currentUser={currentUser} 
              onCreateCommunity={() => setIsCreatingCommunity(true)} 
              onViewProfile={handleViewProfile}
            />
          )}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => setPreviewCommunity(community)} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden bg-zinc-900/10">
                {activeChannelId ? (
                  <ChatWindow 
                    messages={channelMessages[activeChannelId!] || []} 
                    onSendMessage={handleSendMessage} 
                    currentUser={currentUser} 
                    onViewProfile={handleViewProfile}
                    placeholder={`Transmit message to #${activeChannel?.name || 'scope'}...`} 
                  />
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-10 text-[10px] font-bold uppercase tracking-[0.5em] select-none">Void State :: Select Active Node</div>
                )}
                <MemberSidebar 
                  community={activeCommunity} 
                  projectMembers={activeProject?.contributors}
                  onViewProfile={handleViewProfile}
                />
              </div>
            </>
          )}
          {(view === 'profile' || view === 'user-profile') && (
            <Profile 
              user={viewedUser} 
              onLogout={handleLogout} 
              isOwnProfile={viewedUser.id === currentUser.id} 
              onClose={() => setView(activeCommunityId ? 'community' : 'home')}
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Milestone, ProjectResource } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview' | 'user-profile'>('home');
  const [darkMode, setDarkMode] = useState(true);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);

  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Hey team! Ready to build something amazing today?', timestamp: '10:05 AM' },
    ]
  });

  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', tagline: '', description: '' });
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const activeCommunity = communities.find(c => c.id === activeCommunityId);
  const activeProject = projects.find(p => p.id === activeProjectId);
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);
  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const viewedUser = MOCK_USERS.find(u => u.id === selectedUserId) || currentUser;

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
    setView('community');
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
    setView('community');
  };

  const handleViewProfile = (userId: string) => {
    setSelectedUserId(userId);
    setView('user-profile');
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  const handleStartProject = (projectId: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, status: 'Ongoing' } : p));
  };

  const handleAddResource = (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => {
    const newRes: ProjectResource = { id: Date.now().toString(), title, url, type, size };
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, resources: [...p.resources, newRes] } : p));
  };

  if (isLanding) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-8 overflow-hidden relative bg-white dark:bg-zinc-950 transition-colors duration-500">
        <div className="absolute inset-0 vibrant-gradient opacity-10 dark:opacity-20 pointer-events-none"></div>
        <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-brand-500/20 blur-[150px] rounded-full animate-pulse-slow"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-brand-accent/20 blur-[150px] rounded-full animate-pulse-slow"></div>

        <div className="max-w-4xl w-full relative z-10 text-center space-y-12 animate-in fade-in zoom-in duration-1000">
           <div className="inline-flex items-center space-x-2 px-5 py-2 glass-card rounded-full text-brand-600 dark:text-brand-300 text-xs font-bold tracking-widest uppercase border border-brand-500/30 shadow-xl shadow-brand-500/10">
             <span className="flex h-2.5 w-2.5 rounded-full bg-brand-500 mr-2 animate-ping"></span>
             Built for student builders
           </div>

           <div className="space-y-6">
              <h1 className="text-8xl md:text-9xl font-black tracking-tighter text-slate-900 dark:text-white leading-none">
                NEXORA
              </h1>
              <p className="text-xl md:text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-accent tracking-widest uppercase">
                Connect. Collab. Craft.
              </p>
              <p className="text-lg md:text-xl font-medium text-slate-500 dark:text-slate-400 max-w-2xl mx-auto leading-relaxed">
                A home for your next big idea. Join interest-based communities, build technical projects, and grow your reputation with real work.
              </p>
           </div>

           <div className="flex flex-col sm:flex-row items-center justify-center gap-6 pt-6">
              <button 
                onClick={() => { setIsLanding(false); setIsAuthView(true); }}
                className="group relative px-10 py-5 vibrant-gradient text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-2xl shadow-brand-500/40 flex items-center space-x-3"
              >
                <img src="https://www.google.com/favicon.ico" className="w-4 h-4 brightness-0 invert" alt="G" />
                <span>Get Started Now</span>
              </button>
              <button 
                onClick={() => { setIsLanding(false); setView('explore'); }}
                className="px-10 py-5 bg-white dark:bg-zinc-900 text-slate-900 dark:text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-zinc-800 transition-all border border-slate-200 dark:border-white/10"
              >
                Browse Communities
              </button>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-zinc-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans transition-colors duration-300">
      <Sidebar 
        activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} 
        joinedCommunities={communities.filter(c => joinedCommunityIds.includes(c.id))} 
        onSelectCommunity={handleSelectCommunity} 
        onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }} 
        onOpenProfile={() => { handleViewProfile(currentUser.id); }} 
        onOpenHome={() => { setView('home'); setActiveCommunityId(null); }} 
        onCreateCommunity={() => setIsCreatingCommunity(true)} 
      />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-16 flex items-center justify-between px-8 border-b border-slate-200 dark:border-white/5 bg-white/80 dark:bg-zinc-950/80 backdrop-blur-2xl z-20">
          <div className="flex items-center space-x-4">
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">{view.replace('-', ' ')}</span>
            {activeCommunity && (
              <>
                <span className="text-slate-300">/</span>
                <h1 className="text-sm font-black uppercase tracking-widest text-brand-600 dark:text-brand-400">{activeCommunity.name}</h1>
              </>
            )}
          </div>
          <div className="flex items-center space-x-4">
             <button 
               onClick={() => setDarkMode(!darkMode)} 
               className="p-3 bg-slate-100 dark:bg-white/5 rounded-xl hover:scale-110 active:scale-95 transition-all text-slate-500 dark:text-slate-400 hover:text-brand-500"
             >
                {darkMode ? <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg> : <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>}
             </button>
          </div>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && (
            <Home 
              onOpenExplore={() => setView('explore')} 
              joinedCount={joinedCommunityIds.length} 
              currentUser={currentUser} 
              onCreateCommunity={() => setIsCreatingCommunity(true)} 
              onViewProfile={handleViewProfile}
            />
          )}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => setPreviewCommunity(community)} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden bg-white dark:bg-zinc-900/10">
                {activeChannelId ? (
                  <ChatWindow 
                    messages={channelMessages[activeChannelId!] || []} 
                    onSendMessage={handleSendMessage} 
                    currentUser={currentUser} 
                    onViewProfile={handleViewProfile}
                    placeholder={`Message in #${activeChannel?.name || 'general'}...`} 
                  />
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 text-[11px] font-black uppercase tracking-[0.4em] select-none italic">Select a channel or project to begin</div>
                )}
                <MemberSidebar 
                  community={activeCommunity} 
                  projectMembers={activeProject?.contributors}
                  onViewProfile={handleViewProfile}
                />
              </div>
            </>
          )}
          {(view === 'profile' || view === 'user-profile') && (
            <Profile 
              user={viewedUser} 
              onLogout={handleLogout} 
              isOwnProfile={viewedUser.id === currentUser.id} 
              onClose={() => setView(activeCommunityId ? 'community' : 'home')}
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

