import React, { useState, useRef } from 'react';
import { Project, ChatMessage, Milestone, ProjectResource } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onStartProject?: (id: string) => void;
  onAddResource?: (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onStartProject, onAddResource }) => {
  const isMember = project.contributors.includes(currentUserId);
  const isCreator = project.createdBy === currentUserId;
  const [activeTab, setActiveTab] = useState<'overview' | 'roadmap' | 'chat' | 'files'>('overview');
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  const [resTitle, setResTitle] = useState('');
  const [resUrl, setResUrl] = useState('');
  const [resType, setResType] = useState<ProjectResource['type']>('link');
  const [showResForm, setShowResForm] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSendMessage = (content: string) => {
    const user = MOCK_USERS.find(u => u.id === currentUserId);
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUserId,
      senderName: user?.name || 'User',
      senderAvatar: user?.avatar || '',
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleAddRes = (e: React.FormEvent) => {
    e.preventDefault();
    if (!resTitle || !onAddResource) return;

    if (resType === 'file' || resType === 'image') {
      const file = fileInputRef.current?.files?.[0];
      if (file) {
        const localUrl = URL.createObjectURL(file);
        const sizeStr = (file.size / (1024 * 1024)).toFixed(2) + ' MB';
        onAddResource(project.id, resTitle, localUrl, resType, sizeStr);
        setResTitle('');
        setShowResForm(false);
      }
    } else {
      if (resUrl) {
        onAddResource(project.id, resTitle, resUrl, resType);
        setResTitle('');
        setResUrl('');
        setShowResForm(false);
      }
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-transparent overflow-hidden animate-in fade-in duration-500">
      {/* Project Header */}
      <div className="px-10 pt-10 pb-0 border-b border-slate-200 dark:border-white/5 bg-white dark:bg-zinc-900/10">
        <div className="flex items-start justify-between mb-10">
          <div className="flex items-center space-x-6">
            <div className="w-16 h-16 vibrant-gradient rounded-[1.5rem] flex items-center justify-center text-white shadow-2xl">
              <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
            <div>
              <div className="flex items-center space-x-4 mb-2">
                <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white uppercase">{project.name}</h2>
                <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${
                  project.status === 'Ongoing' ? 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20' : 
                  project.status === 'Proposed' ? 'bg-brand-500/10 text-brand-600 border-brand-500/20' :
                  'bg-slate-100 text-slate-500 border-slate-200'
                }`}>
                  {project.status}
                </div>
              </div>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{project.currentVersion || 'v0.1.0'} &bull; {project.contributors.length} Contributors</p>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            {project.status === 'Proposed' && isCreator && (
              <button 
                onClick={() => onStartProject?.(project.id)}
                className="px-8 py-3 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-brand-500/20 active:scale-95"
              >
                Launch Now
              </button>
            )}
            {!isMember && (
              <button className="px-8 py-3 bg-slate-900 dark:bg-white text-white dark:text-zinc-950 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl active:scale-95">
                Join Project
              </button>
            )}
          </div>
        </div>

        {/* Tabs */}
        <div className="flex space-x-10">
          {(['overview', 'roadmap', 'chat', 'files'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`pb-4 text-[11px] font-black uppercase tracking-widest transition-all border-b-4 ${
