              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-10">
        {activeTab === 'overview' && (
          <div className="max-w-4xl space-y-16 animate-in fade-in duration-500">
            <section className="space-y-6">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] flex items-center">
                <span className="w-10 h-1 bg-brand-500/20 mr-4 rounded-full"></span> Description
              </h3>
              <p className="text-slate-600 dark:text-slate-400 text-lg leading-relaxed font-medium">
                {project.description}
              </p>
            </section>

            <section className="space-y-6">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] flex items-center">
                <span className="w-10 h-1 bg-brand-500/20 mr-4 rounded-full"></span> Roles Needed
              </h3>
              <div className="flex flex-wrap gap-3">
