                {project.milestones && project.milestones.map((m, idx) => (
                  <div key={m.id} className="relative group">
                    <div className={`absolute -left-[64px] top-0 w-8 h-8 rounded-full border-4 border-white dark:border-zinc-950 shadow-2xl transition-all flex items-center justify-center ${
