import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Milestone, ProjectResource } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview' | 'user-profile'>('home');
  const [darkMode, setDarkMode] = useState(true);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);
  const [currentUser] = useState<User>(MOCK_USERS[0]);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);

  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [
      { id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Hey team! Ready to build something amazing today?', timestamp: '10:05 AM' },
    ]
  });

  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', description: '', firstMilestone: '' });
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '', roles: '' });

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const activeCommunity = communities.find(c => c.id === activeCommunityId);
  const activeProject = projects.find(p => p.id === activeProjectId);
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);
  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const viewedUser = MOCK_USERS.find(u => u.id === selectedUserId) || currentUser;

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
    setView('community');
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
    setView('community');
  };

  const handleViewProfile = (userId: string) => {
    setSelectedUserId(userId);
    setView('user-profile');
  };

  const handleJoinCommunity = (id: string) => {
    if (!joinedCommunityIds.includes(id)) {
      setJoinedCommunityIds(prev => [...prev, id]);
    }
    handleSelectCommunity(id);
  };

  const handleSendMessage = (content: string) => {
    if (!activeChannelId) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      senderAvatar: currentUser.avatar,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChannelMessages(prev => ({
      ...prev,
      [activeChannelId]: [...(prev[activeChannelId] || []), newMessage]
    }));
  };

  const handleLogout = () => {
    setIsLanding(true);
    setIsAuthView(false);
    setView('home');
    setActiveCommunityId(null);
  };

  const handleStartProject = (projectId: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, status: 'Ongoing' } : p));
  };

  const handleAddResource = (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => {
    const newRes: ProjectResource = { id: Date.now().toString(), title, url, type, size };
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, resources: [...p.resources, newRes] } : p));
  };

  const handleUpdateMilestone = (projectId: string, milestoneId: string, updates: Partial<Milestone>) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== projectId) return p;
      return {
        ...p,
        milestones: p.milestones.map(m => m.id === milestoneId ? { ...m, ...updates } : m)
      };
    }));
  };

  const handleCreateCommunitySubmit = () => {
    if (!newCommunityData.name.trim()) return;
    const newId = `c${Date.now()}`;
    const newComm: Community = {
      id: newId,
      name: newCommunityData.name,
      description: newCommunityData.description,
      icon: '🚀',
      memberCount: 1,
      projectCount: 0,
      channels: [
        { id: `ch-gen-${newId}`, name: 'general', type: 'chat' },
        { id: `ch-pro-${newId}`, name: 'projects', type: 'chat' }
      ],
      tags: ['new'],
      createdBy: currentUser.id,
      roles: [
        { id: 'r1', name: 'Maintainer', color: 'text-brand-500' },
        { id: 'r2', name: 'Member', color: 'text-slate-500' }
      ],
      members: [{ userId: currentUser.id, roleId: 'r1' }]
    };

    // Create a default project with the milestone if provided
    if (newCommunityData.firstMilestone.trim()) {
      const defaultProject: Project = {
        id: `p-init-${newId}`,
        name: `${newCommunityData.name} Initiation`,
        description: 'Initial community setup and goals.',
        communityId: newId,
        status: 'Ongoing',
        techStack: [],
        contributors: [currentUser.id],
        tasks: [],
        milestones: [{
          id: 'm-init',
          title: newCommunityData.firstMilestone,
          description: 'Community starting milestone.',
          dueDate: '',
          status: 'active'
        }],
        resources: [],
        createdBy: currentUser.id
      };
      setProjects(prev => [...prev, defaultProject]);
    }

    setCommunities(prev => [...prev, newComm]);
    setJoinedCommunityIds(prev => [...prev, newId]);
    setIsCreatingCommunity(false);
    setNewCommunityData({ name: '', description: '', firstMilestone: '' });
    handleSelectCommunity(newId);
  };

  const handleCreateProjectSubmit = () => {
    if (!newProjectData.name.trim() || !activeCommunityId) return;
    const newId = `p${Date.now()}`;
    const newProject: Project = {
      id: newId,
      name: newProjectData.name,
      description: newProjectData.description,
      communityId: activeCommunityId,
      status: 'Proposed',
      techStack: [],
      contributors: [currentUser.id],
      tasks: [],
      milestones: [{ id: 'm1', title: 'Phase 1: Kickoff', description: '', dueDate: '', status: 'active' }],
      resources: [],
      rolesNeeded: newProjectData.roles.split(',').map(r => r.trim()).filter(r => !!r),
      createdBy: currentUser.id
    };
    setProjects(prev => [...prev, newProject]);
    setIsCreatingProject(false);
    setNewProjectData({ name: '', description: '', roles: '' });
    setActiveProjectId(newId);
    setActiveChannelId(null);
  };

  if (isLanding) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-8 overflow-hidden relative bg-white dark:bg-zinc-950 transition-colors duration-500">
        <div className="absolute inset-0 vibrant-gradient opacity-10 dark:opacity-20 pointer-events-none"></div>
        <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-brand-500/20 blur-[150px] rounded-full animate-pulse-slow"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-brand-accent/20 blur-[150px] rounded-full animate-pulse-slow"></div>

        <div className="max-w-4xl w-full relative z-10 text-center space-y-12 animate-in fade-in zoom-in duration-1000">
           <div className="inline-flex items-center space-x-2 px-5 py-2 glass-card rounded-full text-brand-600 dark:text-brand-300 text-xs font-bold tracking-widest uppercase border border-brand-500/30 shadow-xl shadow-brand-500/10">
             <span className="flex h-2.5 w-2.5 rounded-full bg-brand-500 mr-2 animate-ping"></span>
             Built for student builders
           </div>

           <div className="space-y-6">
              <h1 className="text-8xl md:text-9xl font-black tracking-tighter text-slate-900 dark:text-white leading-none">
                NEXORA
              </h1>
              <p className="text-xl md:text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-accent tracking-widest uppercase">
                Connect. Collab. Craft.
              </p>
              <p className="text-lg md:text-xl font-medium text-slate-500 dark:text-slate-400 max-w-2xl mx-auto leading-relaxed">
                A home for your next big idea. Join interest-based communities, build technical projects, and grow your reputation with real work.
              </p>
           </div>

           <div className="flex flex-col sm:flex-row items-center justify-center gap-6 pt-6">
              <button 
                onClick={() => { setIsLanding(false); setIsAuthView(true); }}
                className="group relative px-10 py-5 vibrant-gradient text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-2xl shadow-brand-500/40 flex items-center space-x-3"
              >
                <img src="https://www.google.com/favicon.ico" className="w-4 h-4 brightness-0 invert" alt="G" />
                <span>Get Started Now</span>
              </button>
              <button 
                onClick={() => { setIsLanding(false); setView('explore'); }}
                className="px-10 py-5 bg-white dark:bg-zinc-900 text-slate-900 dark:text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-zinc-800 transition-all border border-slate-200 dark:border-white/10"
              >
                Browse Communities
              </button>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-zinc-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans transition-colors duration-300">

      {/* Creation Modal: Community */}
      {isCreatingCommunity && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white dark:bg-zinc-900 w-full max-w-lg p-10 rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-300 border border-slate-200 dark:border-white/10">
            <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-8 tracking-tight uppercase">Create a Space</h2>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Community Name</label>
                <input type="text" placeholder="e.g. Robotics Club" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={newCommunityData.name} onChange={e => setNewCommunityData(p => ({ ...p, name: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Description</label>
                <textarea placeholder="What's the mission?" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-medium h-24" value={newCommunityData.description} onChange={e => setNewCommunityData(p => ({ ...p, description: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Starter Milestone</label>
                <input type="text" placeholder="e.g. Host first meetup" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={newCommunityData.firstMilestone} onChange={e => setNewCommunityData(p => ({ ...p, firstMilestone: e.target.value }))} />
              </div>
              <div className="flex space-x-4 pt-4">
                <button onClick={() => setIsCreatingCommunity(false)} className="flex-1 py-4 bg-slate-200 dark:bg-zinc-800 text-slate-600 dark:text-slate-400 rounded-2xl font-black text-xs uppercase tracking-widest">Cancel</button>
                <button onClick={handleCreateCommunitySubmit} className="flex-[2] py-4 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-brand-500/20">Create Space</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Creation Modal: Project */}
      {isCreatingProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white dark:bg-zinc-900 w-full max-w-lg p-10 rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-300 border border-slate-200 dark:border-white/10">
            <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-8 tracking-tight uppercase">Propose Project</h2>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Project Name</label>
                <input type="text" placeholder="e.g. Open Source CLI" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={newProjectData.name} onChange={e => setNewProjectData(p => ({ ...p, name: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Brief</label>
                <textarea placeholder="Summarize the goal..." className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-medium h-24" value={newProjectData.description} onChange={e => setNewProjectData(p => ({ ...p, description: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Roles Needed (comma separated)</label>
                <input type="text" placeholder="Frontend, Designer, etc..." className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={newProjectData.roles} onChange={e => setNewProjectData(p => ({ ...p, roles: e.target.value }))} />
              </div>
              <div className="flex space-x-4 pt-4">
                <button onClick={() => setIsCreatingProject(false)} className="flex-1 py-4 bg-slate-200 dark:bg-zinc-800 text-slate-600 dark:text-slate-400 rounded-2xl font-black text-xs uppercase tracking-widest">Cancel</button>
                <button onClick={handleCreateProjectSubmit} className="flex-[2] py-4 bg-slate-900 dark:bg-white text-white dark:text-zinc-900 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Propose</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <Sidebar 
        activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} 
        joinedCommunities={communities.filter(c => joinedCommunityIds.includes(c.id))} 
        onSelectCommunity={handleSelectCommunity} 
        onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }} 
        onOpenProfile={() => { handleViewProfile(currentUser.id); }} 
        onOpenHome={() => { setView('home'); setActiveCommunityId(null); }} 
        onCreateCommunity={() => setIsCreatingCommunity(true)} 
      />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-16 flex items-center justify-between px-8 border-b border-slate-200 dark:border-white/5 bg-white/80 dark:bg-zinc-950/80 backdrop-blur-2xl z-20">
          <div className="flex items-center space-x-4">
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">{view.replace('-', ' ')}</span>
            {activeCommunity && (
              <>
                <span className="text-slate-300">/</span>
                <h1 className="text-sm font-black uppercase tracking-widest text-brand-600 dark:text-brand-400">{activeCommunity.name}</h1>
              </>
            )}
          </div>
          <div className="flex items-center space-x-4">
             <button 
               onClick={() => setDarkMode(!darkMode)} 
               className="p-3 bg-slate-100 dark:bg-white/5 rounded-xl hover:scale-110 active:scale-95 transition-all text-slate-500 dark:text-slate-400 hover:text-brand-500"
             >
                {darkMode ? <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg> : <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>}
             </button>
          </div>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && (
            <Home 
              joinedCount={joinedCommunityIds.length} 
              currentUser={currentUser} 
              onCreateCommunity={() => setIsCreatingCommunity(true)} 
              onViewProfile={handleViewProfile}
            />
          )}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => { setPreviewCommunity(community); setView('community-preview'); }} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden bg-white dark:bg-zinc-900/10">
                {activeChannelId ? (
                  <ChatWindow 
                    messages={channelMessages[activeChannelId!] || []} 
                    onSendMessage={handleSendMessage} 
                    currentUser={currentUser} 
                    onViewProfile={handleViewProfile}
                    placeholder={`Message in #${activeChannel?.name || 'general'}...`} 
                  />
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} onUpdateMilestone={handleUpdateMilestone} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 text-[11px] font-black uppercase tracking-[0.4em] select-none italic">Select a channel or project to begin</div>
                )}
                <MemberSidebar 
                  community={activeCommunity} 
                  projectMembers={activeProject?.contributors}
                  onViewProfile={handleViewProfile}
                />
              </div>
            </>
          )}
          {(view === 'profile' || view === 'user-profile') && (
            <Profile 
              user={viewedUser} 
              onLogout={handleLogout} 
              isOwnProfile={viewedUser.id === currentUser.id} 
              onClose={() => setView(activeCommunityId ? 'community' : 'home')}
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Project, ChatMessage, Milestone, ProjectResource } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onStartProject?: (id: string) => void;
  onAddResource?: (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => void;
  onUpdateMilestone?: (projectId: string, milestoneId: string, updates: Partial<Milestone>) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onStartProject, onAddResource, onUpdateMilestone }) => {
  const isMember = project.contributors.includes(currentUserId);
  const isCreator = project.createdBy === currentUserId;
  const [activeTab, setActiveTab] = useState<'overview' | 'milestones' | 'chat' | 'assets'>('overview');
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  const [resTitle, setResTitle] = useState('');
  const [resUrl, setResUrl] = useState('');
  const [resType, setResType] = useState<ProjectResource['type']>('link');
  const [showResForm, setShowResForm] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [selectedMilestone, setSelectedMilestone] = useState<Milestone | null>(null);

  const handleSendMessage = (content: string) => {
    const user = MOCK_USERS.find(u => u.id === currentUserId);
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUserId,
      senderName: user?.name || 'User',
      senderAvatar: user?.avatar || '',
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleAddRes = (e: React.FormEvent) => {
    e.preventDefault();
    if (!resTitle || !onAddResource) return;

    if (resType === 'file' || resType === 'image') {
      const file = fileInputRef.current?.files?.[0];
      if (file) {
        const localUrl = URL.createObjectURL(file);
        const sizeStr = (file.size / (1024 * 1024)).toFixed(2) + ' MB';
        onAddResource(project.id, resTitle, localUrl, resType, sizeStr);
        setResTitle('');
        setShowResForm(false);
      }
    } else {
      if (resUrl) {
        onAddResource(project.id, resTitle, resUrl, resType);
        setResTitle('');
        setResUrl('');
        setShowResForm(false);
      }
    }
  };

  const handleCompleteMilestone = (milestoneId: string, assetId?: string) => {
    if (onUpdateMilestone) {
      onUpdateMilestone(project.id, milestoneId, { 
        status: 'completed',
        attachedAssetId: assetId
      });
      setSelectedMilestone(null);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-transparent overflow-hidden animate-in fade-in duration-500">
      {/* Manage Milestone Modal */}
      {selectedMilestone && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white dark:bg-zinc-900 w-full max-w-md p-10 rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-300 border border-slate-200 dark:border-white/10">
            <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-6 uppercase">Manage Milestone</h2>
            <div className="space-y-6">
              <div className="p-4 bg-slate-50 dark:bg-white/5 rounded-2xl">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Current Goal</p>
                <p className="text-lg font-bold text-slate-800 dark:text-white">{selectedMilestone.title}</p>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Attach Asset (Optional)</label>
                <select 
                  className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-4 rounded-xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold"
                  onChange={(e) => setSelectedMilestone({...selectedMilestone, attachedAssetId: e.target.value})}
                  value={selectedMilestone.attachedAssetId || ""}
                >
                  <option value="">No asset linked</option>
                  {project.resources.map(res => (
                    <option key={res.id} value={res.id}>{res.title} ({res.type})</option>
                  ))}
                </select>
              </div>

              <div className="flex space-x-4 pt-4">
                <button onClick={() => setSelectedMilestone(null)} className="flex-1 py-4 bg-slate-200 dark:bg-zinc-800 text-slate-600 dark:text-slate-400 rounded-2xl font-black text-xs uppercase tracking-widest">Cancel</button>
                <button 
                  onClick={() => handleCompleteMilestone(selectedMilestone.id, selectedMilestone.attachedAssetId)} 
                  className="flex-[2] py-4 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-brand-500/20"
                >
                  Mark as Complete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Project Header */}
      <div className="px-10 pt-10 pb-0 border-b border-slate-200 dark:border-white/5 bg-white dark:bg-zinc-900/10">
        <div className="flex items-start justify-between mb-10">
          <div className="flex items-center space-x-6">
            <div className="w-16 h-16 vibrant-gradient rounded-[1.5rem] flex items-center justify-center text-white shadow-2xl">
              <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
            <div>
              <div className="flex items-center space-x-4 mb-2">
                <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white uppercase">{project.name}</h2>
                <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${
                  project.status === 'Ongoing' ? 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20' : 
                  project.status === 'Proposed' ? 'bg-brand-500/10 text-brand-600 border-brand-500/20' :
                  'bg-slate-100 text-slate-500 border-slate-200'
                }`}>
                  {project.status}
                </div>
              </div>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{project.currentVersion || 'v0.1.0'} &bull; {project.contributors.length} Contributors</p>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            {project.status === 'Proposed' && isCreator && (
              <button 
                onClick={() => onStartProject?.(project.id)}
                className="px-8 py-3 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-brand-500/20 active:scale-95"
              >
                Launch Now
              </button>
            )}
            {!isMember && (
              <button className="px-8 py-3 bg-slate-900 dark:bg-white text-white dark:text-zinc-950 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl active:scale-95">
                Join Project
              </button>
            )}
          </div>
        </div>

        {/* Tabs */}
        <div className="flex space-x-10">
          {(['overview', 'milestones', 'chat', 'assets'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`pb-4 text-[11px] font-black uppercase tracking-widest transition-all border-b-4 ${
                activeTab === tab 
                  ? 'border-brand-500 text-brand-600 dark:text-white' 
                  : 'border-transparent text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-10">
        {activeTab === 'overview' && (
          <div className="max-w-4xl space-y-16 animate-in fade-in duration-500">
            <section className="space-y-6">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] flex items-center">
                <span className="w-10 h-1 bg-brand-500/20 mr-4 rounded-full"></span> Description
              </h3>
              <p className="text-slate-600 dark:text-slate-400 text-lg leading-relaxed font-medium">
                {project.description}
              </p>
            </section>

            <section className="space-y-6">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] flex items-center">
                <span className="w-10 h-1 bg-brand-500/20 mr-4 rounded-full"></span> Roles Needed
              </h3>
              <div className="flex flex-wrap gap-3">
                {project.rolesNeeded?.map(role => (
                  <span key={role} className="bg-white dark:bg-zinc-800 border border-slate-200 dark:border-white/5 px-6 py-4 rounded-3xl text-xs font-black text-slate-700 dark:text-slate-300 uppercase tracking-widest shadow-sm hover:shadow-md transition-all cursor-default">
                    {role}
                  </span>
                ))}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'milestones' && (
          <div className="max-w-2xl animate-in slide-in-from-bottom-8 duration-500">
             <div className="relative space-y-12 pl-12 border-l-4 border-slate-100 dark:border-white/5 ml-6">
                {project.milestones && project.milestones.map((m, idx) => {
                  const linkedAsset = project.resources.find(r => r.id === m.attachedAssetId);
                  return (
                    <div key={m.id} className="relative group">
                      <div className={`absolute -left-[64px] top-0 w-8 h-8 rounded-full border-4 border-white dark:border-zinc-950 shadow-2xl transition-all flex items-center justify-center ${
                        m.status === 'completed' ? 'bg-emerald-500' :
                        m.status === 'active' ? 'bg-brand-500 animate-pulse' : 'bg-slate-200 dark:bg-zinc-800'
                      }`}>
                         {m.status === 'completed' && <svg className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                      </div>
                      <button 
                        onClick={() => isMember && setSelectedMilestone(m)}
                        className={`w-full text-left bg-white dark:bg-zinc-800/50 p-8 rounded-[2rem] border transition-all ${
                          selectedMilestone?.id === m.id ? 'border-brand-500 ring-4 ring-brand-500/5' : 'border-slate-200 dark:border-white/5'
                        } shadow-sm group-hover:shadow-xl group-hover:border-brand-500/30`}
                      >
                         <div className="flex justify-between items-start">
                           <span className={`text-[10px] font-black uppercase tracking-widest mb-3 block ${m.status === 'active' ? 'text-brand-600' : 'text-slate-400'}`}>
                             Phase {idx + 1} &bull; {m.status}
                           </span>
                           {linkedAsset && (
                             <span className="bg-brand-500/10 text-brand-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase border border-brand-500/20">Asset Linked</span>
                           )}
                         </div>
                         <h4 className="text-xl font-black text-slate-900 dark:text-white tracking-tight uppercase">{m.title}</h4>
                         {linkedAsset && (
                           <div className="mt-4 flex items-center space-x-2 text-[10px] font-bold text-slate-500 dark:text-slate-400">
                             <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.826L10.242 9.242" /></svg>
                             <span>{linkedAsset.title}</span>
                           </div>
                         )}
                      </button>
                    </div>
                  );
                })}
             </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="h-full flex flex-col p-0 rounded-[2.5rem] overflow-hidden glass-card shadow-2xl border border-slate-200 dark:border-white/10 animate-in fade-in duration-500">
            {isMember ? (
              <ChatWindow 
                messages={messages} 
                onSendMessage={handleSendMessage} 
                currentUser={MOCK_USERS.find(u => u.id === currentUserId)!}
                placeholder="Message team..."
              />
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-center py-24 opacity-30">
                <svg className="h-20 w-20 mb-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                <p className="text-sm font-black uppercase tracking-widest">Team Chat is private</p>
                <p className="text-xs font-medium mt-2">Join the project to participate in discussions.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'assets' && (
          <div className="space-y-12 animate-in fade-in duration-500">
             <div className="flex items-center justify-between">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] flex items-center">
                  <span className="w-10 h-1 bg-brand-500/20 mr-4 rounded-full"></span> Project Assets
                </h3>
                {isMember && (
                  <button onClick={() => setShowResForm(!showResForm)} className="px-6 py-3 vibrant-gradient text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-brand-500/20 hover:scale-105 transition-all">
                    {showResForm ? 'Cancel' : 'Add Asset'}
                  </button>
                )}
             </div>

             {showResForm && (
                <div className="bg-white dark:bg-zinc-800 p-10 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-white/10 animate-in slide-in-from-top-6">
                  <form onSubmit={handleAddRes} className="space-y-8">
                    <div className="flex space-x-2 p-1.5 bg-slate-100 dark:bg-zinc-950 border border-slate-200 dark:border-white/5 rounded-2xl">
                      {(['link', 'doc', 'image', 'file', 'repo'] as const).map(type => (
                        <button key={type} type="button" onClick={() => setResType(type)} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${resType === type ? 'bg-brand-600 text-white shadow-lg shadow-brand-600/20' : 'text-slate-500 hover:bg-white dark:hover:bg-white/5'}`}>{type}</button>
                      ))}
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Label</label>
                        <input type="text" placeholder="Name this asset..." className="w-full bg-slate-50 dark:bg-zinc-900 border border-slate-200 dark:border-white/10 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold text-slate-900 dark:text-white" value={resTitle} onChange={e => setResTitle(e.target.value)} required />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Asset URL</label>
                        {resType === 'file' || resType === 'image' ? (
                          <input type="file" ref={fileInputRef} className="w-full bg-slate-50 dark:bg-zinc-900 border border-slate-200 dark:border-white/10 p-4 rounded-2xl text-xs text-slate-500" accept={resType === 'image' ? 'image/*' : '*'} onChange={(e) => { if (e.target.files?.[0]) setResUrl(e.target.files[0].name); }} />
                        ) : (
                          <input type="url" placeholder="https://..." className="w-full bg-slate-50 dark:bg-zinc-900 border border-slate-200 dark:border-white/10 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-mono" value={resUrl} onChange={e => setResUrl(e.target.value)} required />
                        )}
                      </div>
                    </div>
                    <button type="submit" className="w-full py-5 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl shadow-brand-500/20 hover:scale-[1.02] active:scale-95 transition-all">Upload Asset</button>
                  </form>
                </div>
             )}

             <div className="bg-white dark:bg-zinc-800/30 rounded-[2.5rem] overflow-hidden border border-slate-200 dark:border-white/10 shadow-sm">
                <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-white/5 border-b border-slate-200 dark:border-white/5">
                    <tr>
                      <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Name</th>
                      <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Type</th>
                      <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Size</th>
                      <th className="px-10 py-6"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                    {project.resources?.map(res => (
                      <tr key={res.id} className="hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-all group">
                        <td className="px-10 py-6">
                           <span className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">{res.title}</span>
                        </td>
                        <td className="px-10 py-6">
                          <span className="text-[10px] font-black text-brand-600 dark:text-brand-400 uppercase tracking-widest bg-brand-500/10 px-4 py-1.5 rounded-full border border-brand-500/20">
                            {res.type}
                          </span>
                        </td>
                        <td className="px-10 py-6 font-bold text-[11px] text-slate-500 uppercase">
                          {res.size || '--'}
                        </td>
                        <td className="px-10 py-6 text-right">
                          <a href={res.url} target="_blank" className="text-slate-400 hover:text-brand-500 transition-colors inline-block p-3 hover:bg-brand-500/10 rounded-xl">
                            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                          </a>
                        </td>
                      </tr>
                    ))}
                    {(!project.resources || project.resources.length === 0) && (
                      <tr><td colSpan={4} className="px-10 py-20 text-center text-sm font-bold text-slate-400 italic">No assets shared in this project node yet</td></tr>
                    )}
                  </tbody>
                </table>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProjectView;

export type ProjectStatus = 'Proposed' | 'Ongoing' | 'Completed';

export interface User {
  id: string;
  name: string;
  role: string;
  college: string;
  bio: string;
  avatar: string;
  skills: string[];
  githubUrl: string;
  linkedinUrl: string;
  portfolioUrl?: string;
  cvUrl?: string;
  reputation: number;
  hasOnboarded?: boolean;
}

export interface Task {
  id: string;
  title: string;
  status: 'todo' | 'in-progress' | 'done';
  assignee?: string;
}

export interface ProjectResource {
  id: string;
  title: string;
  url: string;
  type: 'link' | 'doc' | 'repo' | 'image' | 'file';
  size?: string;
}

export interface Milestone {
  id: string;
  title: string;
  description: string;
  dueDate: string;
  status: 'pending' | 'active' | 'completed';
  attachedAssetId?: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  communityId: string;
  status: ProjectStatus;
  techStack: string[];
  contributors: string[];
  tasks: Task[];
  milestones: Milestone[];
  resources: ProjectResource[];
  repositoryUrl?: string;
  currentVersion?: string;
  rolesNeeded?: string[];
  createdBy: string;
}

export interface Role {
  id: string;
  name: string;
  color: string;
}

export interface Member {
  userId: string;
  roleId: string;
}

export interface Community {
  id: string;
  name: string;
  description: string;
  icon: string;
  memberCount: number;
  projectCount: number;
  channels: Channel[];
  tags: string[];
  createdBy: string;
  roles: Role[];
  members: Member[];
}

export interface Channel {
  id: string;
  name: string;
  type: 'chat' | 'project-list';
}

export interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderAvatar: string;
  content: string;
  timestamp: string;
}

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChannelPanel from './components/ChannelPanel';
import ProjectView from './components/ProjectView';
import Profile from './components/Profile';
import Home from './components/Home';
import Explore from './components/Explore';
import CommunityDashboard from './components/CommunityDashboard';
import ChatWindow from './components/ChatWindow';
import MemberSidebar from './components/MemberSidebar';
import { MOCK_COMMUNITIES, MOCK_PROJECTS, MOCK_USERS } from './constants';
import { Community, Project, ChatMessage, User, Milestone, ProjectResource } from './types';

const App: React.FC = () => {
  const [isLanding, setIsLanding] = useState(true);
  const [isAuthView, setIsAuthView] = useState(false);
  const [isOnboarding, setIsOnboarding] = useState(false);
  const [activeCommunityId, setActiveCommunityId] = useState<string | null>(null);
  const [activeChannelId, setActiveChannelId] = useState<string | null>(null);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [view, setView] = useState<'home' | 'community' | 'profile' | 'explore' | 'community-preview' | 'user-profile'>('home');
  const [darkMode, setDarkMode] = useState(true);
  const [joinedCommunityIds, setJoinedCommunityIds] = useState<string[]>(['c1']);
  const [previewCommunity, setPreviewCommunity] = useState<Community | null>(null);

  const [currentUser, setCurrentUser] = useState<User>({
    ...MOCK_USERS[0],
    hasOnboarded: true
  });

  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
  const [communities, setCommunities] = useState<Community[]>(MOCK_COMMUNITIES);
  const [projects, setProjects] = useState<Project[]>(MOCK_PROJECTS);

  const [channelMessages, setChannelMessages] = useState<Record<string, ChatMessage[]>>({
    'ch1': [{ id: '1', senderId: 'u2', senderName: 'Sarah Chen', senderAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah', content: 'Hey team! Ready to build something amazing today?', timestamp: '10:05 AM' }]
  });

  const [isCreatingCommunity, setIsCreatingCommunity] = useState(false);
  const [newCommunityData, setNewCommunityData] = useState({ name: '', description: '', firstMilestone: '' });

  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ 
    name: '', 
    description: '', 
    roles: '', 
    initialMilestones: ['Phase 1: Kickoff'] 
  });

  const [onboardingForm, setOnboardingForm] = useState({
    bio: '',
    interests: '',
    portfolio: '',
    github: '',
    linkedin: '',
    cv: ''
  });

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [darkMode]);

  const activeCommunity = communities.find(c => c.id === activeCommunityId);
  const activeProject = projects.find(p => p.id === activeProjectId);
  const activeChannel = activeCommunity?.channels.find(c => c.id === activeChannelId);
  const communityProjects = projects.filter(p => p.communityId === activeCommunityId);
  const viewedUser = MOCK_USERS.find(u => u.id === selectedUserId) || currentUser;

  const handleSelectCommunity = (id: string | null) => {
    setActiveCommunityId(id);
    const community = communities.find(c => c.id === id);
    if (community) {
      setActiveChannelId(community.channels[0].id);
      setActiveProjectId(null);
      setView('community');
    } else {
      setView('home');
    }
  };

  const handleSelectChannel = (id: string) => {
    setActiveChannelId(id);
    setActiveProjectId(null);
    setView('community');
  };

  const handleSelectProject = (id: string) => {
    setActiveProjectId(id);
    setActiveChannelId(null);
    setView('community');
  };

  const handleViewProfile = (userId: string) => {
    setSelectedUserId(userId);
    setView('user-profile');
  };

  const handleLogin = () => {
    setIsLanding(false);
    if (!currentUser.hasOnboarded) {
      setIsOnboarding(true);
    } else {
      setView('home');
    }
  };

  const handleOnboardingSubmit = () => {
    setCurrentUser(prev => ({
      ...prev,
      bio: onboardingForm.bio,
      skills: onboardingForm.interests.split(',').map(s => s.trim()),
      portfolioUrl: onboardingForm.portfolio,
      githubUrl: onboardingForm.github,
      linkedinUrl: onboardingForm.linkedin,
      cvUrl: onboardingForm.cv,
      hasOnboarded: true
    }));
    setIsOnboarding(false);
    setView('home');
  };

  const handleUpdateMilestone = (projectId: string, milestoneId: string, updates: Partial<Milestone>) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== projectId) return p;
      const updatedMilestones = p.milestones.map(m => m.id === milestoneId ? { ...m, ...updates } : m);
      const allCompleted = updatedMilestones.every(m => m.status === 'completed');
      return {
        ...p,
        milestones: updatedMilestones,
        status: allCompleted ? 'Completed' : p.status
      };
    }));
  };

  const handleReorderMilestones = (projectId: string, milestones: Milestone[]) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, milestones } : p));
  };

  const handleAddMilestone = (projectId: string, title: string) => {
    const newMilestone: Milestone = {
      id: `m-${Date.now()}`,
      title,
      description: '',
      dueDate: '',
      status: 'pending'
    };
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, milestones: [...p.milestones, newMilestone] } : p));
  };

  const handleCreateCommunitySubmit = () => {
    if (!newCommunityData.name.trim()) return;
    const newId = `c${Date.now()}`;
    const newComm: Community = {
      id: newId,
      name: newCommunityData.name,
      description: newCommunityData.description,
      icon: '🚀',
      memberCount: 1,
      projectCount: 0,
      channels: [
        { id: `ch-gen-${newId}`, name: 'general', type: 'chat' },
        { id: `ch-pro-${newId}`, name: 'projects', type: 'chat' }
      ],
      tags: ['new'],
      createdBy: currentUser.id,
      roles: [{ id: 'r1', name: 'Maintainer', color: 'text-brand-500' }, { id: 'r2', name: 'Member', color: 'text-slate-500' }],
      members: [{ userId: currentUser.id, roleId: 'r1' }]
    };

    if (newCommunityData.firstMilestone.trim()) {
      const defaultProject: Project = {
        id: `p-init-${newId}`,
        name: `${newCommunityData.name} Setup`,
        description: 'Initial community setup.',
        communityId: newId,
        status: 'Ongoing',
        techStack: [],
        contributors: [currentUser.id],
        tasks: [],
        milestones: [{ id: 'm-init', title: newCommunityData.firstMilestone, description: '', dueDate: '', status: 'active' }],
        resources: [],
        createdBy: currentUser.id
      };
      setProjects(prev => [...prev, defaultProject]);
    }

    setCommunities(prev => [...prev, newComm]);
    setJoinedCommunityIds(prev => [...prev, newId]);
    setIsCreatingCommunity(false);
    setNewCommunityData({ name: '', description: '', firstMilestone: '' });
    handleSelectCommunity(newId);
  };

  const handleCreateProjectSubmit = () => {
    if (!newProjectData.name.trim() || !activeCommunityId) return;
    const newId = `p${Date.now()}`;
    const milestones: Milestone[] = newProjectData.initialMilestones.map((m, i) => ({
      id: `m${i}-${Date.now()}`,
      title: m,
      description: '',
      dueDate: '',
      status: i === 0 ? 'active' : 'pending'
    }));

    const newProject: Project = {
      id: newId,
      name: newProjectData.name,
      description: newProjectData.description,
      communityId: activeCommunityId,
      status: 'Proposed',
      techStack: [],
      contributors: [currentUser.id],
      tasks: [],
      milestones: milestones,
      resources: [],
      rolesNeeded: newProjectData.roles.split(',').map(r => r.trim()).filter(r => !!r),
      createdBy: currentUser.id
    };
    setProjects(prev => [...prev, newProject]);
    setIsCreatingProject(false);
    setNewProjectData({ name: '', description: '', roles: '', initialMilestones: ['Phase 1: Kickoff'] });
    setActiveProjectId(newId);
  };

  if (isLanding) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-8 overflow-hidden relative bg-white dark:bg-zinc-950 transition-colors duration-500">
        <div className="absolute inset-0 vibrant-gradient opacity-10 dark:opacity-20 pointer-events-none"></div>
        <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-brand-500/20 blur-[150px] rounded-full animate-pulse-slow"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-brand-accent/20 blur-[150px] rounded-full animate-pulse-slow"></div>

        <div className="max-w-4xl w-full relative z-10 text-center space-y-12 animate-in fade-in zoom-in duration-1000">
           <div className="inline-flex items-center space-x-2 px-5 py-2 glass-card rounded-full text-brand-600 dark:text-brand-300 text-xs font-bold tracking-widest uppercase border border-brand-500/30 shadow-xl shadow-brand-500/10">
             <span className="flex h-2.5 w-2.5 rounded-full bg-brand-500 mr-2 animate-ping"></span>
             Built for student builders
           </div>

           <div className="space-y-6">
              <h1 className="text-8xl md:text-9xl font-black tracking-tighter text-slate-900 dark:text-white leading-none">NEXORA</h1>
              <p className="text-xl md:text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-brand-600 to-brand-accent tracking-widest uppercase">Connect. Collab. Craft.</p>
              <p className="text-lg md:text-xl font-medium text-slate-500 dark:text-slate-400 max-w-2xl mx-auto leading-relaxed">Join interest-based communities, build technical projects, and grow your reputation with real work.</p>
           </div>

           <div className="flex flex-col sm:flex-row items-center justify-center gap-6 pt-6">
              <button 
                onClick={handleLogin}
                className="group relative px-10 py-5 vibrant-gradient text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-2xl shadow-brand-500/40 flex items-center space-x-4"
              >
                <img src="https://www.google.com/favicon.ico" className="w-5 h-5 brightness-0 invert" alt="" />
                <span>Continue with Google</span>
              </button>
           </div>
        </div>
      </div>
    );
  }

  if (isOnboarding) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-zinc-950 flex items-center justify-center p-6 transition-colors duration-500">
        <div className="w-full max-w-3xl bg-white dark:bg-zinc-900 rounded-[3rem] p-12 shadow-2xl border border-slate-200 dark:border-white/10">
          <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-2 uppercase tracking-tight">Complete Profile</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-10 font-medium">Tell the community who you are and what you craft.</p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Bio</label>
                <textarea className="w-full bg-slate-50 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm h-32" value={onboardingForm.bio} onChange={e => setOnboardingForm(p => ({ ...p, bio: e.target.value }))} placeholder="What drives you?" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Interests/Skills (comma separated)</label>
                <input type="text" className="w-full bg-slate-50 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={onboardingForm.interests} onChange={e => setOnboardingForm(p => ({ ...p, interests: e.target.value }))} placeholder="React, Python, Figma..." />
              </div>
            </div>
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">GitHub</label>
                  <input type="url" className="w-full bg-slate-50 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm" value={onboardingForm.github} onChange={e => setOnboardingForm(p => ({ ...p, github: e.target.value }))} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">LinkedIn</label>
                  <input type="url" className="w-full bg-slate-50 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm" value={onboardingForm.linkedin} onChange={e => setOnboardingForm(p => ({ ...p, linkedin: e.target.value }))} />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Portfolio URL</label>
                <input type="url" className="w-full bg-slate-50 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm" value={onboardingForm.portfolio} onChange={e => setOnboardingForm(p => ({ ...p, portfolio: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">CV / Resume Link</label>
                <input type="url" className="w-full bg-slate-50 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm" value={onboardingForm.cv} onChange={e => setOnboardingForm(p => ({ ...p, cv: e.target.value }))} />
              </div>
            </div>
          </div>
          <button onClick={handleOnboardingSubmit} className="w-full mt-12 py-5 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl shadow-brand-500/20 hover:scale-[1.02] active:scale-95 transition-all">Complete Setup</button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-zinc-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans transition-colors duration-300">

      {/* Creation Modal: Community */}
      {isCreatingCommunity && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white dark:bg-zinc-900 w-full max-w-lg p-10 rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-300 border border-slate-200 dark:border-white/10">
            <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-8 tracking-tight uppercase">Create a Space</h2>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Community Name</label>
                <input type="text" placeholder="e.g. Robotics Club" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={newCommunityData.name} onChange={e => setNewCommunityData(p => ({ ...p, name: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Description</label>
                <textarea placeholder="What's the mission?" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-medium h-24" value={newCommunityData.description} onChange={e => setNewCommunityData(p => ({ ...p, description: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Starter Milestone</label>
                <input type="text" placeholder="e.g. Host first meetup" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={newCommunityData.firstMilestone} onChange={e => setNewCommunityData(p => ({ ...p, firstMilestone: e.target.value }))} />
              </div>
              <div className="flex space-x-4 pt-4">
                <button onClick={() => setIsCreatingCommunity(false)} className="flex-1 py-4 bg-slate-200 dark:bg-zinc-800 text-slate-600 dark:text-slate-400 rounded-2xl font-black text-xs uppercase tracking-widest">Cancel</button>
                <button onClick={handleCreateCommunitySubmit} className="flex-[2] py-4 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-brand-500/20">Create Space</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Creation Modal: Project */}
      {isCreatingProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white dark:bg-zinc-900 w-full max-w-xl p-10 rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-300 border border-slate-200 dark:border-white/10">
            <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-8 tracking-tight uppercase">Propose Project</h2>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Project Name</label>
                <input type="text" placeholder="e.g. Open Source CLI" className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-5 rounded-2xl outline-none focus:ring-2 focus:ring-brand-500 text-sm font-bold" value={newProjectData.name} onChange={e => setNewProjectData(p => ({ ...p, name: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Initial Milestones</label>
                <div className="space-y-2">
                  {newProjectData.initialMilestones.map((m, idx) => (
                    <div key={idx} className="flex items-center space-x-2">
                      <input type="text" className="flex-1 bg-slate-100 dark:bg-zinc-950 border border-slate-200 dark:border-white/5 p-3 rounded-xl text-xs font-bold" value={m} onChange={e => {
                        const next = [...newProjectData.initialMilestones];
                        next[idx] = e.target.value;
                        setNewProjectData(p => ({ ...p, initialMilestones: next }));
                      }} />
                      {idx > 0 && (
                        <button onClick={() => {
                          const next = newProjectData.initialMilestones.filter((_, i) => i !== idx);
                          setNewProjectData(p => ({ ...p, initialMilestones: next }));
                        }} className="p-2 text-rose-500">×</button>
                      )}
                    </div>
                  ))}
                  <button onClick={() => setNewProjectData(p => ({ ...p, initialMilestones: [...p.initialMilestones, 'New Milestone'] }))} className="text-[9px] font-black text-brand-500 uppercase">+ Add Another</button>
                </div>
              </div>
              <div className="flex space-x-4 pt-4">
                <button onClick={() => setIsCreatingProject(false)} className="flex-1 py-4 bg-slate-200 dark:bg-zinc-800 rounded-2xl font-black text-xs uppercase tracking-widest">Cancel</button>
                <button onClick={handleCreateProjectSubmit} className="flex-[2] py-4 bg-slate-900 dark:bg-white text-white dark:text-zinc-900 rounded-2xl font-black text-xs uppercase tracking-widest">Propose</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <Sidebar 
        activeCommunityId={view === 'explore' || view === 'community-preview' ? 'explore' : activeCommunityId} 
        joinedCommunities={communities.filter(c => joinedCommunityIds.includes(c.id))} 
        onSelectCommunity={handleSelectCommunity} 
        onOpenExplore={() => { setView('explore'); setActiveCommunityId(null); }} 
        onOpenProfile={() => { handleViewProfile(currentUser.id); }} 
        onOpenHome={() => { setView('home'); setActiveCommunityId(null); }} 
        onCreateCommunity={() => setIsCreatingCommunity(true)} 
      />

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-16 flex items-center justify-between px-8 border-b border-slate-200 dark:border-white/5 bg-white/80 dark:bg-zinc-950/80 backdrop-blur-2xl z-20">
          <div className="flex items-center space-x-4">
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">{view.replace('-', ' ')}</span>
            {activeCommunity && (
              <>
                <span className="text-slate-300">/</span>
                <h1 className="text-sm font-black uppercase tracking-widest text-brand-600 dark:text-brand-400">{activeCommunity.name}</h1>
              </>
            )}
          </div>
          <div className="flex items-center space-x-4">
             <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-slate-100 dark:bg-white/5 rounded-xl hover:scale-110 active:scale-95 transition-all text-slate-500 dark:text-slate-400 hover:text-brand-500">
                {darkMode ? <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg> : <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>}
             </button>
          </div>
        </header>

        <main className="flex-1 flex overflow-hidden">
          {view === 'home' && <Home joinedCount={joinedCommunityIds.length} currentUser={currentUser} onCreateCommunity={() => setIsCreatingCommunity(true)} onViewProfile={handleViewProfile} />}
          {view === 'explore' && <Explore joinedIds={joinedCommunityIds} onPreviewCommunity={community => { setPreviewCommunity(community); setView('community-preview'); }} />}
          {view === 'community-preview' && previewCommunity && <CommunityDashboard community={previewCommunity} onJoin={() => handleJoinCommunity(previewCommunity.id)} isJoined={joinedCommunityIds.includes(previewCommunity.id)} projects={projects} />}
          {view === 'community' && activeCommunity && (
            <>
              <ChannelPanel community={activeCommunity} projects={communityProjects} activeChannelId={activeChannelId} activeProjectId={activeProjectId} onSelectChannel={handleSelectChannel} onSelectProject={handleSelectProject} onCreateProject={() => setIsCreatingProject(true)} />
              <div className="flex-1 flex overflow-hidden bg-white dark:bg-zinc-900/10">
                {activeChannelId ? (
                  <ChatWindow messages={channelMessages[activeChannelId!] || []} onSendMessage={handleSendMessage} currentUser={currentUser} onViewProfile={handleViewProfile} placeholder={`Message in #${activeChannel?.name || 'general'}...`} />
                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} onUpdateMilestone={handleUpdateMilestone} onReorderMilestones={handleReorderMilestones} onAddMilestone={handleAddMilestone} />
                ) : (
                   <div className="flex-1 flex items-center justify-center opacity-30 text-[11px] font-black uppercase tracking-[0.4em] select-none italic">Select a channel or project to begin</div>
                )}
                <MemberSidebar community={activeCommunity} projectMembers={activeProject?.contributors} onViewProfile={handleViewProfile} />
              </div>
            </>
          )}
          {(view === 'profile' || view === 'user-profile') && <Profile user={viewedUser} onLogout={handleLogout} isOwnProfile={viewedUser.id === currentUser.id} onClose={() => setView(activeCommunityId ? 'community' : 'home')} />}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Project, ChatMessage, Milestone, ProjectResource } from '../types';
import { MOCK_USERS } from '../constants';
import ChatWindow from './ChatWindow';

interface ProjectViewProps {
  project: Project;
  currentUserId: string;
  onStartProject?: (id: string) => void;
  onAddResource?: (projectId: string, title: string, url: string, type: ProjectResource['type'], size?: string) => void;
  onUpdateMilestone?: (projectId: string, milestoneId: string, updates: Partial<Milestone>) => void;
  onReorderMilestones?: (projectId: string, milestones: Milestone[]) => void;
  onAddMilestone?: (projectId: string, title: string) => void;
}

const ProjectView: React.FC<ProjectViewProps> = ({ project, currentUserId, onStartProject, onAddResource, onUpdateMilestone, onReorderMilestones, onAddMilestone }) => {
  const isMember = project.contributors.includes(currentUserId);
  const [activeTab, setActiveTab] = useState<'overview' | 'milestones' | 'chat' | 'assets'>('overview');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showResForm, setShowResForm] = useState(false);
  const [resTitle, setResTitle] = useState('');
  const [resUrl, setResUrl] = useState('');
  const [resType, setResType] = useState<ProjectResource['type']>('link');
  const [showMilestoneForm, setShowMilestoneForm] = useState(false);
  const [newMilestoneTitle, setNewMilestoneTitle] = useState('');
  const [selectedMilestone, setSelectedMilestone] = useState<Milestone | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSendMessage = (content: string) => {
    const user = MOCK_USERS.find(u => u.id === currentUserId);
    const newMessage: ChatMessage = { id: Date.now().toString(), senderId: currentUserId, senderName: user?.name || 'User', senderAvatar: user?.avatar || '', content, timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleAddRes = (e: React.FormEvent) => {
    e.preventDefault();
    if (!resTitle || !onAddResource) return;
    if (resType === 'file' || resType === 'image') {
      const file = fileInputRef.current?.files?.[0];
      if (file) {
        onAddResource(project.id, resTitle, URL.createObjectURL(file), resType, (file.size / (1024 * 1024)).toFixed(2) + ' MB');
        setResTitle(''); setShowResForm(false);
      }
    } else if (resUrl) {
      onAddResource(project.id, resTitle, resUrl, resType);
      setResTitle(''); setResUrl(''); setShowResForm(false);
    }
  };

  const moveMilestone = (idx: number, dir: 'up' | 'down') => {
    if (!onReorderMilestones) return;
    const nextIdx = dir === 'up' ? idx - 1 : idx + 1;
    if (nextIdx < 0 || nextIdx >= project.milestones.length) return;
    const next = [...project.milestones];
    [next[idx], next[nextIdx]] = [next[nextIdx], next[idx]];
    onReorderMilestones(project.id, next);
  };

  const handleCompleteMilestone = (mId: string, assetId?: string) => {
    onUpdateMilestone?.(project.id, mId, { status: 'completed', attachedAssetId: assetId });
    setSelectedMilestone(null);
  };

  return (
    <div className="flex-1 flex flex-col bg-transparent overflow-hidden animate-in fade-in duration-500">
      {selectedMilestone && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white dark:bg-zinc-900 w-full max-w-md p-10 rounded-[2.5rem] shadow-2xl animate-in zoom-in border border-slate-200 dark:border-white/10">
            <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-6 uppercase">Mark Complete</h2>
            <div className="space-y-6">
              <div className="p-4 bg-slate-50 dark:bg-white/5 rounded-2xl">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Goal</p>
                <p className="text-lg font-bold text-slate-800 dark:text-white">{selectedMilestone.title}</p>
              </div>
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Attach Proof / Asset</label>
                <select className="w-full bg-slate-100 dark:bg-zinc-950 border-2 border-slate-200 dark:border-white/5 p-4 rounded-xl outline-none text-sm font-bold" onChange={(e) => setSelectedMilestone({...selectedMilestone, attachedAssetId: e.target.value})} value={selectedMilestone.attachedAssetId || ""}>
                  <option value="">No asset linked</option>
                  {project.resources.map(res => <option key={res.id} value={res.id}>{res.title}</option>)}
                </select>
              </div>
              <div className="flex space-x-4">
                <button onClick={() => setSelectedMilestone(null)} className="flex-1 py-4 bg-slate-200 dark:bg-zinc-800 rounded-2xl font-black text-xs uppercase">Cancel</button>
                <button onClick={() => handleCompleteMilestone(selectedMilestone.id, selectedMilestone.attachedAssetId)} className="flex-[2] py-4 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase shadow-xl">Complete</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="px-10 pt-10 pb-0 border-b border-slate-200 dark:border-white/5 bg-white dark:bg-zinc-900/10">
        <div className="flex items-start justify-between mb-10">
          <div className="flex items-center space-x-6">
            <div className="w-16 h-16 vibrant-gradient rounded-[1.5rem] flex items-center justify-center text-white shadow-2xl">
              <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
            </div>
            <div>
              <div className="flex items-center space-x-4 mb-2">
                <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white uppercase">{project.name}</h2>
                <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${project.status === 'Ongoing' ? 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20' : project.status === 'Completed' ? 'bg-brand-500/10 text-brand-600 border-brand-500/20 shadow-[0_0_10px_rgba(99,102,241,0.2)]' : 'bg-slate-100 text-slate-500 border-slate-200'}`}>{project.status}</div>
              </div>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{project.currentVersion || 'v0.1.0'} &bull; {project.contributors.length} Contributors</p>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            {project.status === 'Proposed' && project.createdBy === currentUserId && (
              <button onClick={() => onStartProject?.(project.id)} className="px-8 py-3 vibrant-gradient text-white rounded-2xl font-black text-xs uppercase shadow-xl shadow-brand-500/20">Launch Project</button>
            )}
            {!isMember && <button className="px-8 py-3 bg-slate-900 dark:bg-white text-white dark:text-zinc-950 rounded-2xl font-black text-xs uppercase shadow-xl">Join Project</button>}
          </div>
        </div>
        <div className="flex space-x-10">
          {(['overview', 'milestones', 'chat', 'assets'] as const).map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`pb-4 text-[11px] font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === tab ? 'border-brand-500 text-brand-600 dark:text-white' : 'border-transparent text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}>{tab}</button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-10">
        {activeTab === 'overview' && (
          <div className="max-w-4xl space-y-16 animate-in fade-in">
            <section className="space-y-6">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] flex items-center"><span className="w-10 h-1 bg-brand-500/20 mr-4 rounded-full"></span> Description</h3>
              <p className="text-slate-600 dark:text-slate-400 text-lg leading-relaxed font-medium">{project.description}</p>
            </section>
            <section className="space-y-6">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] flex items-center"><span className="w-10 h-1 bg-brand-500/20 mr-4 rounded-full"></span> Roles Needed</h3>
              <div className="flex flex-wrap gap-3">
                {project.rolesNeeded?.map(role => <span key={role} className="bg-white dark:bg-zinc-800 border border-slate-200 dark:border-white/5 px-6 py-4 rounded-3xl text-xs font-black text-slate-700 dark:text-slate-300 uppercase tracking-widest shadow-sm">{role}</span>)}
              </div>
