                ) : activeProject ? (
                  <ProjectView project={activeProject} currentUserId={currentUser.id} onStartProject={handleStartProject} onAddResource={handleAddResource} onUpdateMilestone={handleUpdateMilestone} onReorderMilestones={handleReorderMilestones} onAddMilestone={handleAddMilestone} />
                ) : (
