          )}
          {(view === 'profile' || view === 'user-profile') && <Profile user={viewedUser} onLogout={handleLogout} isOwnProfile={viewedUser.id === currentUser.id} onClose={() => setView(activeCommunityId ? 'community' : 'home')} />}
